#!/usr/bin/env python3
"""Reproducible geometric direct-sun and shade sensitivity study.

This is deliberately a concept-stage geometry test, not a statutory
insolation calculation, an energy model or a thermal-comfort simulation.  It
uses the exact ``PROTOTYPES`` objects that drive the competition drawings,
NREL SPA through pvlib, typed receptors for the three architectural orders and
an explicit orientation / height / tree-canopy sensitivity matrix.
"""

from __future__ import annotations

import argparse
import ast
import csv
import hashlib
import importlib.metadata
import json
import math
import os
import shutil
import tempfile
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable
from zoneinfo import ZoneInfo

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
import pvlib
from shapely import contains_xy
from shapely.affinity import rotate as geom_rotate
from shapely.affinity import translate as geom_translate
from shapely.geometry import LineString, Point, box, mapping, shape
from shapely.ops import unary_union

WORKSPACE = Path(__file__).resolve().parents[1]
BUILDER_PATH = WORKSPACE / "tools" / "build_shared_floor.py"
# The private repository's tracked package is the sole build authority.  The
# linked organizer checkout supplies policy scripts only and must never become
# a second mutable submission tree.
PACKAGE = WORKSPACE / "submission" / "shared-floor-jingzhang"
PACKAGE_MANIFEST = PACKAGE / "manifest.json"
PACKAGE_COMPILER_SNAPSHOT = PACKAGE / "visual" / "assets" / "compiler-source.json"
SITE_BOUNDARY_PATH = PACKAGE / "geometry" / "site_boundary.geojson"
HARNESS_LATEST = WORKSPACE / "studio-projects" / "jingzhang-world" / "harness" / "latest.json"
DEFAULT_OUTPUT_ROOT = WORKSPACE / "studio-projects" / "jingzhang-world" / "analysis" / "direct-sun-v1"

METHOD_VERSION = "jingzhang-direct-sun-v1.1.0"
EVIDENCE_EPOCH = "2026-08-12T00:00:00Z"
LOCATION = {
    "latitude": 39.98086972782049,
    "longitude": 116.34770915575874,
    "altitude_m": 0.0,
    "timezone": "Asia/Shanghai",
    "basis": "coordinate-space centroid of the disclosed provisional WGS84 site geometry; low-confidence orientation seed; zero altitude used for geometric comparison",
}
ROTATIONS_DEG = (-15.0, -7.5, 0.0, 7.5, 15.0)
HEIGHT_SCALES = (0.8, 1.0, 1.2)
TREE_STATES = {
    "none": {"diameter_scale": 0.0, "crown_height_m": 0.0},
    "young": {"diameter_scale": 0.75, "crown_height_m": 6.0},
    "declared": {"diameter_scale": 1.0, "crown_height_m": 8.0},
    "mature": {"diameter_scale": 1.25, "crown_height_m": 10.0},
}
INTERVAL_HOURS = 0.5


def load_prototypes(path: Path) -> dict[str, dict[str, Any]]:
    """Read the literal geometry payload without importing the package builder."""
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    assignments = [
        node for node in tree.body
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "PROTOTYPES"
    ]
    if len(assignments) != 1:
        raise RuntimeError(f"expected one literal PROTOTYPES assignment, found {len(assignments)}")
    try:
        value = ast.literal_eval(assignments[0].value)
    except (TypeError, ValueError) as error:
        raise RuntimeError("PROTOTYPES must remain a literal data payload") from error
    if set(value) != {"proof", "origin", "exchange"}:
        raise RuntimeError("PROTOTYPES schema drift: expected proof/origin/exchange")
    for key, prototype in value.items():
        missing = {"elements", "routes", "courts", "trees", "tree_canopy_diameter_m", "climate_edges"} - set(prototype)
        if missing:
            raise RuntimeError(f"PROTOTYPES[{key}] lacks {sorted(missing)}")
        for element in prototype["elements"]:
            required = {"id", "x", "y", "w", "d", "height", "storeys", "layer"}
            if required - set(element):
                raise RuntimeError(f"prototype element {element.get('id')} is incomplete")
        for edge in prototype["climate_edges"]:
            required = {"id", "x", "y", "w", "d", "deployment_mode"}
            if required - set(edge):
                raise RuntimeError(f"prototype climate edge {edge.get('id')} is incomplete")
            if edge["deployment_mode"] not in {"fixed_all_season", "hot_season_retractable"}:
                raise RuntimeError(f"unsupported climate-edge deployment mode: {edge['deployment_mode']}")
            if "roof_height_m" not in edge:
                raise RuntimeError(f"prototype climate edge lacks typed roof height: {edge['id']}")
    return value


PROTOTYPES = load_prototypes(BUILDER_PATH)


def rect(cx: float, cy: float, width: float, depth: float):
    return box(cx - width / 2, cy - depth / 2, cx + width / 2, cy + depth / 2)


def local_element_geometry(element: dict[str, Any]):
    geometry = rect(0, 0, element["w"], element["d"])
    if element.get("angle"):
        geometry = geom_rotate(geometry, element["angle"], origin=(0, 0), use_radians=False)
    return geom_translate(geometry, xoff=element["x"], yoff=element["y"])


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def canonical_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)


def value_sha256(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n", encoding="utf-8")


def rounded(value: float, places: int = 6) -> float:
    return round(float(value), places)


def dependency_versions() -> dict[str, str]:
    names = ("pvlib", "pandas", "numpy", "shapely", "matplotlib")
    return {name: importlib.metadata.version(name) for name in names}


def make_contract(grid_spacing_m: float = 1.0, created_at: str = EVIDENCE_EPOCH) -> dict[str, Any]:
    return {
        "schema_version": "jingzhang-direct-sun-contract-v1",
        "method_version": METHOD_VERSION,
        "created_at": created_at,
        "location": LOCATION,
        "solar_position": {
            "engine": "pvlib.solarposition.spa_python",
            "method": "NREL SPA, numpy implementation, delta_t calculated by pvlib",
            "elevation_field": "elevation",
            "reference": "NREL Solar Position Algorithm",
            "altitude_policy": "0 m comparison datum; site altitude is not asserted and the study is geometric",
        },
        "time_windows": [
            {"id": "winter_solstice", "date": "2026-12-21", "first_center": "09:15", "last_center": "14:45", "step_minutes": 30, "season": "winter"},
            {"id": "summer_solstice", "date": "2026-06-21", "first_center": "10:15", "last_center": "16:45", "step_minutes": 30, "season": "summer"},
            {"id": "hot_season_check", "date": "2026-07-21", "first_center": "10:15", "last_center": "16:45", "step_minutes": 30, "season": "summer"},
        ],
        "interval_hours": INTERVAL_HOURS,
        "grid_spacing_m": float(grid_spacing_m),
        "orientation_deg": list(ROTATIONS_DEG),
        "height_scales": list(HEIGHT_SCALES),
        "tree_states": TREE_STATES,
        "receptors": {
            "proof": "controlled field minus authored building footprints",
            "origin": "Care, Forum and Learning courts separately, minus authored building footprints",
            "exchange": "four 3 m exterior public approaches; the all-weather central hall is excluded",
            "supplemental_human_routes": "Proof observation route and Origin public lane are reported separately and never averaged into the activity-area mean",
        },
        "shade_layers": {
            "building": "swept ground shadow of each vertical prism",
            "fixed_typed_roof": "horizontal typed roof shadow active in winter and summer; recorded separately from building shadow",
            "hot_season_retractable_roof": "horizontal typed seasonal roof shadow active in June and July only and asserted absent from winter masks",
            "weather_cover": "authored roof footprint overlap reported separately from projected solar shade",
            "tree": "horizontal opaque crown disk translated from analyst-assumed crown height; summer sensitivity only",
        },
        "claim_boundary": {
            "geometry_only": True,
            "statutory_insolation": False,
            "daylight": False,
            "energy": False,
            "thermal_comfort_utci_or_mrt": False,
            "glare": False,
            "clouds_and_reflections": False,
            "existing_context_or_topography": False,
            "tree_species_or_leaf_area": False,
            "official_boundary": False,
        },
    }


def _time_centers(window: dict[str, Any]) -> list[datetime]:
    tz = ZoneInfo(LOCATION["timezone"])
    start = datetime.fromisoformat(f"{window['date']}T{window['first_center']}:00").replace(tzinfo=tz)
    end = datetime.fromisoformat(f"{window['date']}T{window['last_center']}:00").replace(tzinfo=tz)
    values = pd.date_range(start=start, end=end, freq=f"{window['step_minutes']}min")
    return [stamp.to_pydatetime() for stamp in values]


def solar_samples(contract: dict[str, Any]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for window in contract["time_windows"]:
        times = pd.DatetimeIndex(_time_centers(window))
        position = pvlib.solarposition.spa_python(
            times,
            LOCATION["latitude"],
            LOCATION["longitude"],
            altitude=LOCATION["altitude_m"],
            temperature=12.0,
            delta_t=None,
            how="numpy",
        )
        for stamp, row in position.iterrows():
            elevation = float(row["elevation"])
            if elevation <= 0:
                raise RuntimeError(f"sample below horizon: {stamp.isoformat()}")
            records.append(
                {
                    "window_id": window["id"],
                    "season": window["season"],
                    "timestamp": stamp.isoformat(),
                    "apparent_elevation_deg": rounded(row["apparent_elevation"]),
                    "elevation_deg": rounded(elevation),
                    "azimuth_deg": rounded(row["azimuth"]),
                    "interval_hours": contract["interval_hours"],
                }
            )
    return records


def shadow_vector(height_m: float, elevation_deg: float, azimuth_deg: float) -> tuple[float, float]:
    if height_m < 0:
        raise ValueError("height must be non-negative")
    if not 0 < elevation_deg <= 90:
        raise ValueError("solar elevation must be within (0, 90]")
    length = 0.0 if elevation_deg == 90 else height_m / math.tan(math.radians(elevation_deg))
    azimuth = math.radians(azimuth_deg)
    return (-length * math.sin(azimuth), -length * math.cos(azimuth))


def prism_shadow(footprint, height_m: float, elevation_deg: float, azimuth_deg: float):
    if footprint.geom_type != "Polygon" or footprint.interiors or abs(footprint.convex_hull.area - footprint.area) > 1e-7:
        raise ValueError("v1 prism shadow supports convex, hole-free footprints only")
    dx, dy = shadow_vector(height_m, elevation_deg, azimuth_deg)
    roof_projection = geom_translate(footprint, xoff=dx, yoff=dy)
    return unary_union([footprint, roof_projection]).convex_hull


def horizontal_roof_shadow(footprint, height_m: float, elevation_deg: float, azimuth_deg: float):
    """Project an opaque horizontal roof plane onto the ground.

    Unlike a vertical building prism, an open canopy does not shade the whole
    swept volume between its plan position and the projected roof.  Treating
    it as a prism would invent an opaque wall around the canopy.
    """
    dx, dy = shadow_vector(height_m, elevation_deg, azimuth_deg)
    return geom_translate(footprint, xoff=dx, yoff=dy)


def _rotate(geometry, rotation_deg: float):
    if not rotation_deg:
        return geometry
    return geom_rotate(geometry, rotation_deg, origin=(0, 0), use_radians=False)


def prototype_buildings(prototype_key: str, rotation_deg: float = 0.0, height_scale: float = 1.0) -> list[dict[str, Any]]:
    result = []
    for element in PROTOTYPES[prototype_key]["elements"]:
        result.append(
            {
                "id": element["id"],
                "geometry": _rotate(local_element_geometry(element), rotation_deg),
                "height_m": float(element["height"]) * height_scale,
                "layer": element["layer"],
            }
        )
    return result


def prototype_eaves(prototype_key: str, rotation_deg: float = 0.0):
    prototype = PROTOTYPES[prototype_key]
    parts = [_rotate(rect(edge["x"], edge["y"], edge["w"], edge["d"]), rotation_deg) for edge in prototype.get("climate_edges", [])]
    return unary_union(parts) if parts else box(0, 0, 0, 0)


def prototype_typed_roofs(prototype_key: str, rotation_deg: float = 0.0) -> list[dict[str, Any]]:
    """Return typed roof objects without erasing height or seasonal state."""
    roofs: list[dict[str, Any]] = []
    for edge in PROTOTYPES[prototype_key].get("climate_edges", []):
        roofs.append(
            {
                "id": edge["id"],
                "geometry": _rotate(rect(edge["x"], edge["y"], edge["w"], edge["d"]), rotation_deg),
                "height_m": float(edge["roof_height_m"]),
                "deployment_mode": edge["deployment_mode"],
            }
        )
    return roofs


def prototype_tree_crowns(prototype_key: str, rotation_deg: float, tree_state: str) -> list[Any]:
    state = TREE_STATES[tree_state]
    if state["diameter_scale"] == 0:
        return []
    prototype = PROTOTYPES[prototype_key]
    radius = prototype["tree_canopy_diameter_m"] * state["diameter_scale"] / 2
    return [_rotate(Point(x, y).buffer(radius, quad_segs=24), rotation_deg) for x, y in prototype["trees"]]


def receptor_zones(prototype_key: str, rotation_deg: float = 0.0) -> dict[str, Any]:
    prototype = PROTOTYPES[prototype_key]
    base_buildings = unary_union([local_element_geometry(item) for item in prototype["elements"]])
    if prototype_key in {"proof", "origin"}:
        zones = {
            label.replace(" ", "_"): box(x, y, x + width, y + depth).difference(base_buildings)
            for x, y, width, depth, label in prototype["courts"]
        }
    elif prototype_key == "exchange":
        hall = next(local_element_geometry(item) for item in prototype["elements"] if item["id"] == "DZ-CANOPY")
        minx, miny, maxx, maxy = hall.bounds
        zones = {
            "west_approach": LineString([(-72, 0), (minx, 0)]).buffer(1.5, cap_style="flat"),
            "east_approach": LineString([(maxx, 0), (72, 0)]).buffer(1.5, cap_style="flat"),
            "south_approach": LineString([(0, -72), (0, miny)]).buffer(1.5, cap_style="flat"),
            "north_approach": LineString([(0, maxy), (0, 72)]).buffer(1.5, cap_style="flat"),
        }
        zones = {name: geometry.difference(base_buildings).difference(hall) for name, geometry in zones.items()}
    else:
        raise KeyError(prototype_key)
    rotated = {name: _rotate(geometry.buffer(0), rotation_deg) for name, geometry in zones.items()}
    if any(geometry.is_empty or geometry.area <= 1 for geometry in rotated.values()):
        raise RuntimeError(f"empty receptor in {prototype_key}")
    return rotated


def route_receptor_zones(prototype_key: str, rotation_deg: float = 0.0) -> dict[str, Any]:
    """Additional human-route receptors, kept out of the activity-area mean."""
    prototype = PROTOTYPES[prototype_key]
    base_buildings = unary_union([local_element_geometry(item) for item in prototype["elements"]])
    if prototype_key == "proof":
        zones = {"observation_route": LineString([(-75, -66), (72, -66)]).buffer(1.5, cap_style="flat").difference(base_buildings)}
    elif prototype_key == "origin":
        zones = {"public_lane": LineString([(-82, -27), (82, -27)]).buffer(1.5, cap_style="flat").difference(base_buildings)}
    else:
        zones = {}
    return {name: _rotate(geometry.buffer(0), rotation_deg) for name, geometry in zones.items()}


def sample_geometry(geometry, spacing_m: float) -> tuple[np.ndarray, np.ndarray]:
    minx, miny, maxx, maxy = geometry.bounds
    # Cell centres are anchored to the receptor bounds.  Global half-grid
    # anchoring placed points exactly on the ±1.5 m boundary of a 3 m route
    # and under-counted every HALL approach by one third.
    x0 = minx + spacing_m / 2
    y0 = miny + spacing_m / 2
    xs = np.arange(x0, maxx, spacing_m, dtype=np.float64)
    ys = np.arange(y0, maxy, spacing_m, dtype=np.float64)
    xx, yy = np.meshgrid(xs, ys)
    flat_x, flat_y = xx.ravel(), yy.ravel()
    mask = contains_xy(geometry, flat_x, flat_y)
    selected_x, selected_y = flat_x[mask], flat_y[mask]
    if not len(selected_x):
        raise RuntimeError("receptor grid contains no points")
    return selected_x, selected_y


def _shadow_mask(geometry, x: np.ndarray, y: np.ndarray) -> np.ndarray:
    if geometry.is_empty:
        return np.zeros(len(x), dtype=bool)
    return contains_xy(geometry, x, y)


def evaluate_variant(
    prototype_key: str,
    rotation_deg: float,
    height_scale: float,
    tree_state: str,
    samples: list[dict[str, Any]],
    grid_spacing_m: float = 1.0,
    *,
    return_spatial: bool = False,
) -> dict[str, Any]:
    buildings = prototype_buildings(prototype_key, rotation_deg, height_scale)
    typed_roofs = prototype_typed_roofs(prototype_key, rotation_deg)
    fixed_roofs = [item for item in typed_roofs if item["deployment_mode"] == "fixed_all_season"]
    seasonal_roofs = [item for item in typed_roofs if item["deployment_mode"] == "hot_season_retractable"]
    fixed_eaves = unary_union([item["geometry"] for item in fixed_roofs]) if fixed_roofs else box(0, 0, 0, 0)
    hot_season_eaves = unary_union([item["geometry"] for item in typed_roofs]) if typed_roofs else box(0, 0, 0, 0)
    crowns = prototype_tree_crowns(prototype_key, rotation_deg, tree_state)
    crown_height = TREE_STATES[tree_state]["crown_height_m"]
    activity_zones = receptor_zones(prototype_key, rotation_deg)
    route_zones = route_receptor_zones(prototype_key, rotation_deg)
    zones = {**activity_zones, **route_zones}
    grids = {name: sample_geometry(geometry, grid_spacing_m) for name, geometry in zones.items()}
    summer_windows = list(dict.fromkeys(item["window_id"] for item in samples if item["season"] == "summer"))
    summer_window_counts = {window_id: sum(item["window_id"] == window_id for item in samples) for window_id in summer_windows}
    summer_samples = [item for item in samples if item["season"] == "summer"]
    state: dict[str, dict[str, Any]] = {}
    accounting_errors: list[float] = []
    for name, (x, y) in grids.items():
        state[name] = {
            "x": x,
            "y": y,
            "winter_building_unshadowed_steps": np.zeros(len(x), dtype=np.int16),
            "winter_architecture_unshadowed_steps": np.zeros(len(x), dtype=np.int16),
            "summer_building_shade_steps": np.zeros(len(x), dtype=np.int16),
            "summer_roof_shade_steps": np.zeros(len(x), dtype=np.int16),
            "summer_architecture_shade_steps": np.zeros(len(x), dtype=np.int16),
            "summer_total_shade_steps": np.zeros(len(x), dtype=np.int16),
            "summer_interval_building": [],
            "summer_interval_architecture": [],
            "summer_interval_total": [],
            "summer_window_building_steps": {window_id: np.zeros(len(x), dtype=np.int16) for window_id in summer_windows},
            "summer_window_architecture_steps": {window_id: np.zeros(len(x), dtype=np.int16) for window_id in summer_windows},
            "summer_window_total_steps": {window_id: np.zeros(len(x), dtype=np.int16) for window_id in summer_windows},
            "fixed_roof_plan_cover_fraction": float(np.mean(_shadow_mask(fixed_eaves, x, y))),
            "hot_season_roof_plan_cover_fraction": float(np.mean(_shadow_mask(hot_season_eaves, x, y))),
        }

    winter_count = sum(item["season"] == "winter" for item in samples)
    summer_count = sum(item["season"] == "summer" for item in samples)
    for sample in samples:
        building_shadow = unary_union(
            [
                prism_shadow(item["geometry"], item["height_m"], sample["elevation_deg"], sample["azimuth_deg"])
                for item in buildings
            ]
        )
        active_roofs = fixed_roofs + (seasonal_roofs if sample["season"] == "summer" else [])
        roof_shadow = unary_union(
            [
                horizontal_roof_shadow(item["geometry"], item["height_m"], sample["elevation_deg"], sample["azimuth_deg"])
                for item in active_roofs
            ]
        ) if active_roofs else box(0, 0, 0, 0)
        architecture_shadow = unary_union([building_shadow, roof_shadow])
        if sample["season"] == "summer" and crowns:
            dx, dy = shadow_vector(crown_height, sample["elevation_deg"], sample["azimuth_deg"])
            tree_shadow = unary_union([geom_translate(crown, xoff=dx, yoff=dy) for crown in crowns])
            total_shadow = unary_union([architecture_shadow, tree_shadow])
        else:
            total_shadow = architecture_shadow

        for zone in state.values():
            building_mask = _shadow_mask(building_shadow, zone["x"], zone["y"])
            roof_mask = _shadow_mask(roof_shadow, zone["x"], zone["y"])
            architecture_mask = _shadow_mask(architecture_shadow, zone["x"], zone["y"])
            if sample["season"] == "winter":
                zone["winter_building_unshadowed_steps"] += (~building_mask).astype(np.int16)
                zone["winter_architecture_unshadowed_steps"] += (~architecture_mask).astype(np.int16)
                accounting_errors.append(abs(float(np.mean(~architecture_mask)) + float(np.mean(architecture_mask)) - 1.0))
            else:
                total_mask = _shadow_mask(total_shadow, zone["x"], zone["y"])
                accounting_errors.append(abs(float(np.mean(~total_mask)) + float(np.mean(total_mask)) - 1.0))
                zone["summer_building_shade_steps"] += building_mask.astype(np.int16)
                zone["summer_roof_shade_steps"] += roof_mask.astype(np.int16)
                zone["summer_architecture_shade_steps"] += architecture_mask.astype(np.int16)
                zone["summer_total_shade_steps"] += total_mask.astype(np.int16)
                zone["summer_window_building_steps"][sample["window_id"]] += building_mask.astype(np.int16)
                zone["summer_window_architecture_steps"][sample["window_id"]] += architecture_mask.astype(np.int16)
                zone["summer_window_total_steps"][sample["window_id"]] += total_mask.astype(np.int16)
                zone["summer_interval_building"].append(float(np.mean(building_mask)))
                zone["summer_interval_architecture"].append(float(np.mean(architecture_mask)))
                zone["summer_interval_total"].append(float(np.mean(total_mask)))

    zone_metrics: dict[str, dict[str, float | int]] = {}
    combined_winter_building: list[np.ndarray] = []
    combined_winter_architecture: list[np.ndarray] = []
    combined_building: list[np.ndarray] = []
    combined_roof: list[np.ndarray] = []
    combined_architecture: list[np.ndarray] = []
    combined_total: list[np.ndarray] = []
    total_points = 0
    for name, zone in state.items():
        winter_building_hours = zone["winter_building_unshadowed_steps"].astype(np.float64) * INTERVAL_HOURS
        winter_architecture_hours = zone["winter_architecture_unshadowed_steps"].astype(np.float64) * INTERVAL_HOURS
        summer_building = zone["summer_building_shade_steps"].astype(np.float64) / summer_count
        summer_roof = zone["summer_roof_shade_steps"].astype(np.float64) / summer_count
        summer_architecture = zone["summer_architecture_shade_steps"].astype(np.float64) / summer_count
        summer_total = zone["summer_total_shade_steps"].astype(np.float64) / summer_count
        if name in activity_zones:
            combined_winter_building.append(winter_building_hours)
            combined_winter_architecture.append(winter_architecture_hours)
            combined_building.append(summer_building)
            combined_roof.append(summer_roof)
            combined_architecture.append(summer_architecture)
            combined_total.append(summer_total)
            total_points += len(winter_building_hours)
        zone_metrics[name] = {
            "sample_point_count": len(winter_building_hours),
            "winter_mean_building_unshadowed_hours": rounded(np.mean(winter_building_hours)),
            "winter_mean_architecture_unshadowed_hours": rounded(np.mean(winter_architecture_hours)),
            "winter_area_fraction_building_unshadowed_ge_2h": rounded(np.mean(winter_building_hours >= 2.0)),
            "winter_area_fraction_building_unshadowed_ge_3h": rounded(np.mean(winter_building_hours >= 3.0)),
            "winter_area_fraction_architecture_unshadowed_ge_2h": rounded(np.mean(winter_architecture_hours >= 2.0)),
            "winter_area_fraction_architecture_unshadowed_ge_3h": rounded(np.mean(winter_architecture_hours >= 3.0)),
            "summer_building_mean_shadow_fraction": rounded(np.mean(summer_building)),
            "summer_typed_roof_mean_shadow_fraction": rounded(np.mean(summer_roof)),
            "summer_architecture_mean_shadow_fraction": rounded(np.mean(summer_architecture)),
            "summer_total_mean_shadow_fraction": rounded(np.mean(summer_total)),
            "summer_worst_interval_building_shadow_fraction": rounded(min(zone["summer_interval_building"])),
            "summer_worst_interval_architecture_shadow_fraction": rounded(min(zone["summer_interval_architecture"])),
            "summer_worst_interval_total_shadow_fraction": rounded(min(zone["summer_interval_total"])),
            "summer_tree_contribution_beyond_architecture_fraction": rounded(np.mean(summer_total) - np.mean(summer_architecture)),
            "fixed_roof_plan_weather_cover_fraction": rounded(zone["fixed_roof_plan_cover_fraction"]),
            "hot_season_roof_plan_weather_cover_fraction": rounded(zone["hot_season_roof_plan_cover_fraction"]),
        }
        for window_id in summer_windows:
            count = summer_window_counts[window_id]
            window_building = zone["summer_window_building_steps"][window_id].astype(np.float64) / count
            window_architecture = zone["summer_window_architecture_steps"][window_id].astype(np.float64) / count
            window_total = zone["summer_window_total_steps"][window_id].astype(np.float64) / count
            zone_metrics[name][f"{window_id}_building_mean_shadow_fraction"] = rounded(np.mean(window_building))
            zone_metrics[name][f"{window_id}_architecture_mean_shadow_fraction"] = rounded(np.mean(window_architecture))
            zone_metrics[name][f"{window_id}_total_mean_shadow_fraction"] = rounded(np.mean(window_total))

    winter_building_all = np.concatenate(combined_winter_building)
    winter_architecture_all = np.concatenate(combined_winter_architecture)
    building_all = np.concatenate(combined_building)
    roof_all = np.concatenate(combined_roof)
    architecture_all = np.concatenate(combined_architecture)
    total_all = np.concatenate(combined_total)
    architecture_intervals = []
    building_intervals = []
    total_intervals = []
    for index in range(summer_count):
        weighted_building = sum(state[name]["summer_interval_building"][index] * len(state[name]["x"]) for name in activity_zones) / total_points
        weighted_arch = sum(state[name]["summer_interval_architecture"][index] * len(state[name]["x"]) for name in activity_zones) / total_points
        weighted_total = sum(state[name]["summer_interval_total"][index] * len(state[name]["x"]) for name in activity_zones) / total_points
        building_intervals.append(weighted_building)
        architecture_intervals.append(weighted_arch)
        total_intervals.append(weighted_total)
    worst_interval_index = int(np.argmin(total_intervals))

    variant_id = f"{prototype_key}-r{rotation_deg:+05.1f}-h{height_scale:.1f}-tree-{tree_state}"
    result: dict[str, Any] = {
        "variant_id": variant_id,
        "prototype": prototype_key,
        "rotation_deg": rotation_deg,
        "height_scale": height_scale,
        "tree_state": tree_state,
        "receptor_area_sqm": rounded(sum(item.area for item in activity_zones.values()), 3),
        "route_receptor_area_sqm": rounded(sum(item.area for item in route_zones.values()), 3),
        "sample_point_count": total_points,
        "route_receptor_sample_point_count": sum(len(state[name]["x"]) for name in route_zones),
        "winter_sample_count": winter_count,
        "summer_sample_count": summer_count,
        "winter_mean_building_unshadowed_hours": rounded(np.mean(winter_building_all)),
        "winter_mean_architecture_unshadowed_hours": rounded(np.mean(winter_architecture_all)),
        "winter_area_fraction_building_unshadowed_ge_2h": rounded(np.mean(winter_building_all >= 2.0)),
        "winter_area_fraction_building_unshadowed_ge_3h": rounded(np.mean(winter_building_all >= 3.0)),
        "winter_area_fraction_architecture_unshadowed_ge_2h": rounded(np.mean(winter_architecture_all >= 2.0)),
        "winter_area_fraction_architecture_unshadowed_ge_3h": rounded(np.mean(winter_architecture_all >= 3.0)),
        "summer_building_mean_shadow_fraction": rounded(np.mean(building_all)),
        "summer_typed_roof_mean_shadow_fraction": rounded(np.mean(roof_all)),
        "summer_architecture_mean_shadow_fraction": rounded(np.mean(architecture_all)),
        "summer_total_mean_shadow_fraction": rounded(np.mean(total_all)),
        "summer_worst_interval_building_shadow_fraction": rounded(min(building_intervals)),
        "summer_worst_interval_architecture_shadow_fraction": rounded(min(architecture_intervals)),
        "summer_worst_interval_total_shadow_fraction": rounded(min(total_intervals)),
        "summer_tree_contribution_beyond_architecture_fraction": rounded(np.mean(total_all) - np.mean(architecture_all)),
        "winter_hot_season_roof_active_count": 0,
        "fixed_roof_plan_weather_cover_fraction": rounded(
            sum(state[name]["fixed_roof_plan_cover_fraction"] * len(state[name]["x"]) for name in activity_zones) / total_points
        ),
        "hot_season_roof_plan_weather_cover_fraction": rounded(
            sum(state[name]["hot_season_roof_plan_cover_fraction"] * len(state[name]["x"]) for name in activity_zones) / total_points
        ),
        "accounting_max_error": rounded(max(accounting_errors) if accounting_errors else 0.0, 12),
        "summer_worst_interval_timestamp": summer_samples[worst_interval_index]["timestamp"],
        "summer_worst_interval_window_id": summer_samples[worst_interval_index]["window_id"],
        "zone_metrics": zone_metrics,
    }
    for window_id in summer_windows:
        count = summer_window_counts[window_id]
        window_building = np.concatenate([state[name]["summer_window_building_steps"][window_id].astype(np.float64) / count for name in activity_zones])
        window_architecture = np.concatenate([state[name]["summer_window_architecture_steps"][window_id].astype(np.float64) / count for name in activity_zones])
        window_total = np.concatenate([state[name]["summer_window_total_steps"][window_id].astype(np.float64) / count for name in activity_zones])
        result[f"{window_id}_building_mean_shadow_fraction"] = rounded(np.mean(window_building))
        result[f"{window_id}_architecture_mean_shadow_fraction"] = rounded(np.mean(window_architecture))
        result[f"{window_id}_total_mean_shadow_fraction"] = rounded(np.mean(window_total))
    if return_spatial:
        result["_spatial"] = {
            name: {
                "x": zone["x"],
                "y": zone["y"],
                "winter_hours": zone["winter_architecture_unshadowed_steps"].astype(np.float64) * INTERVAL_HOURS,
                "summer_shade": zone["summer_total_shade_steps"].astype(np.float64) / summer_count,
            }
            for name, zone in state.items()
        }
    return result


def public_result(result: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in result.items() if not key.startswith("_")}


def variant_specs() -> Iterable[tuple[str, float, float, str]]:
