def summarize(rows: list[dict[str, Any]]) -> dict[str, Any]:
    output: dict[str, Any] = {}
    for prototype_key in PROTOTYPES:
        group = [row for row in rows if row["prototype"] == prototype_key]
        baseline = next(row for row in group if row["rotation_deg"] == 0 and row["height_scale"] == 1 and row["tree_state"] == "declared")
        no_tree = next(row for row in group if row["rotation_deg"] == 0 and row["height_scale"] == 1 and row["tree_state"] == "none")
        tree_envelopes = {}
        for tree_state in TREE_STATES:
            state_group = [row for row in group if row["tree_state"] == tree_state]
            tree_envelopes[tree_state] = {
                "case_count": len(state_group),
                "winter_mean_architecture_unshadowed_hours_min": rounded(min(row["winter_mean_architecture_unshadowed_hours"] for row in state_group)),
                "winter_mean_architecture_unshadowed_hours_max": rounded(max(row["winter_mean_architecture_unshadowed_hours"] for row in state_group)),
                "summer_total_mean_shadow_fraction_min": rounded(min(row["summer_total_mean_shadow_fraction"] for row in state_group)),
                "summer_total_mean_shadow_fraction_max": rounded(max(row["summer_total_mean_shadow_fraction"] for row in state_group)),
            }
        output[prototype_key] = {
            "name_en": PROTOTYPES[prototype_key]["name_en"],
            "name_zh": PROTOTYPES[prototype_key]["name_zh"],
            "baseline_declared_tree": baseline,
            "baseline_no_tree": no_tree,
            "sensitivity_envelope_by_tree_state": tree_envelopes,
            "robustness_range_all_variants": {
                "winter_mean_architecture_unshadowed_hours_min": rounded(min(row["winter_mean_architecture_unshadowed_hours"] for row in group)),
                "winter_mean_architecture_unshadowed_hours_max": rounded(max(row["winter_mean_architecture_unshadowed_hours"] for row in group)),
                "summer_building_mean_shadow_fraction_min": rounded(min(row["summer_building_mean_shadow_fraction"] for row in group)),
                "summer_building_mean_shadow_fraction_max": rounded(max(row["summer_building_mean_shadow_fraction"] for row in group)),
                "summer_architecture_mean_shadow_fraction_min": rounded(min(row["summer_architecture_mean_shadow_fraction"] for row in group)),
                "summer_architecture_mean_shadow_fraction_max": rounded(max(row["summer_architecture_mean_shadow_fraction"] for row in group)),
                "summer_total_mean_shadow_fraction_min": rounded(min(row["summer_total_mean_shadow_fraction"] for row in group)),
                "summer_total_mean_shadow_fraction_max": rounded(max(row["summer_total_mean_shadow_fraction"] for row in group)),
            },
        }
    return output


def write_csv(path: Path, rows: list[dict[str, Any]], fields: list[str]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        for row in rows:
            writer.writerow({field: row.get(field, "") for field in fields})


def _plot_polygon(ax, geometry, **kwargs) -> None:
    geoms = list(geometry.geoms) if geometry.geom_type == "MultiPolygon" else [geometry]
    for geom in geoms:
        x, y = geom.exterior.xy
        ax.plot(x, y, **kwargs)


