def validate_against_harness_snapshot(design_state: dict[str, Any]) -> dict[str, Any]:
    """Prove that the literal prototype payload matches the selected C03 snapshot."""
    offsets = {"proof": -240.0, "origin": 0.0, "exchange": 240.0}
    mass_by_id = {item["id"]: item for item in design_state["masses"]}
    expected_mass_ids: set[str] = set()
    expected_route_ids: set[str] = set()
    expected_room_ids: set[str] = set()
    room_prefix = {"proof": "PROOF", "origin": "ORIGIN", "exchange": "EXCHANGE"}
    tree_prefix = {"proof": "PROOF", "origin": "ORIGIN", "exchange": "EXCHANGE"}

    for key, prototype in PROTOTYPES.items():
        offset = offsets[key]
        for element in prototype["elements"]:
            expected_mass_ids.add(element["id"])
            actual = mass_by_id.get(element["id"])
            expected = {
                "x": float(element["x"]) + offset,
                "y": float(element["y"]),
                "width": float(element["w"]),
                "depth": float(element["d"]),
                "height": float(element["height"]),
                "storeys": int(element["storeys"]),
                "layer": element["layer"],
                "angle": float(element.get("angle", 0)),
                "public_through_route": bool(element.get("public_through_route", False)),
                "summer_only_shade": False,
            }
            if actual is None or any(actual.get(field) != value for field, value in expected.items()):
                raise RuntimeError(f"prototype mass mismatch against C03 snapshot: {element['id']}")
        for index, (x, y) in enumerate(prototype["trees"], start=1):
            tree_id = f"TREE-{tree_prefix[key]}-{index}"
            expected_mass_ids.add(tree_id)
            actual = mass_by_id.get(tree_id)
            diameter = float(prototype["tree_canopy_diameter_m"])
            expected = {
                "x": float(x) + offset,
                "y": float(y),
                "width": diameter,
                "depth": diameter,
                "height": 8,
                "storeys": 0,
                "layer": "canopy",
                "angle": 0,
                "public_through_route": True,
                "summer_only_shade": True,
            }
            if actual is None or any(actual.get(field) != value for field, value in expected.items()):
                raise RuntimeError(f"prototype tree mismatch against C03 snapshot: {tree_id}")

        routes = {item["id"]: item for item in design_state["routes"]}
        for index, (start, end, kind) in enumerate(prototype["routes"], start=1):
            route_id = f"SF-ROUTE-{room_prefix[key]}-{index}"
            expected_route_ids.add(route_id)
            actual = routes.get(route_id)
            expected_start = [float(start[0]) + offset, float(start[1])]
            expected_end = [float(end[0]) + offset, float(end[1])]
            if actual is None or actual["start"] != expected_start or actual["end"] != expected_end or actual["kind"] != kind:
                raise RuntimeError(f"prototype route mismatch against C03 snapshot: {route_id}")

        rooms = {item["id"]: item for item in design_state["public_rooms"]}
        for index, (x, y, width, depth, label) in enumerate(prototype["courts"], start=1):
            room_id = f"SF-{room_prefix[key]}-{index}"
            expected_room_ids.add(room_id)
            actual = rooms.get(room_id)
            expected_center = [float(x) + float(width) / 2 + offset, float(y) + float(depth) / 2]
            if (
                actual is None
                or [actual["x"], actual["y"]] != expected_center
                or actual["width"] != width
                or actual["depth"] != depth
                or actual["kind"] != label
            ):
                raise RuntimeError(f"prototype court mismatch against C03 snapshot: {room_id}")

    actual_prototype_mass_ids = {item["id"] for item in design_state["masses"]}
    if actual_prototype_mass_ids != expected_mass_ids:
        raise RuntimeError("C03 mass inventory differs from the literal prototype inventory")
    actual_prototype_routes = {item["id"] for item in design_state["routes"] if item["id"].startswith("SF-ROUTE-")}
    if actual_prototype_routes != expected_route_ids:
        raise RuntimeError("C03 prototype route inventory differs from the literal prototype inventory")
    actual_rooms = {item["id"] for item in design_state["public_rooms"]}
    if actual_rooms != expected_room_ids:
        raise RuntimeError("C03 public-room inventory differs from the literal prototype inventory")
    return {
        "mass_count": len(expected_mass_ids),
        "prototype_route_count": len(expected_route_ids),
        "public_room_count": len(expected_room_ids),
        "field_compare_pass": True,
    }


def validate_location_seed() -> dict[str, Any]:
    if not SITE_BOUNDARY_PATH.is_file():
        raise RuntimeError("provisional site boundary is missing")
    feature_collection = json.loads(SITE_BOUNDARY_PATH.read_text(encoding="utf-8"))
    geometry = shape(feature_collection["features"][0]["geometry"])
    longitude, latitude = geometry.centroid.x, geometry.centroid.y
    if abs(latitude - LOCATION["latitude"]) > 1e-10 or abs(longitude - LOCATION["longitude"]) > 1e-10:
        raise RuntimeError("analysis location no longer matches the provisional site centroid")
    return {
        "site_boundary_sha256": file_sha256(SITE_BOUNDARY_PATH),
        "centroid_latitude": latitude,
        "centroid_longitude": longitude,
        "centroid_assertion_pass": True,
        "centroid_method": "Shapely coordinate-space centroid of the provisional WGS84 polygon",
        "claim_boundary": "low-confidence provisional orientation seed; not an official site boundary or survey coordinate",
    }


def legacy_compatibility(c03_state: dict[str, Any], harness_metrics: dict[str, Any]) -> dict[str, Any]:
    """Reproduce the old gross-room noon proxy without contaminating v1."""
    def mass_polygon(item: dict[str, Any]):
        geometry = rect(item["x"], item["y"], item["width"], item["depth"])
        return geom_rotate(geometry, item.get("angle", 0), origin=(item["x"], item["y"]), use_radians=False) if item.get("angle") else geometry

    def legacy_shadow(item: dict[str, Any], altitude_deg: float):
        polygon = mass_polygon(item)
        distance = item["height"] / math.tan(math.radians(altitude_deg))
        moved = geom_translate(polygon, yoff=distance)
        return unary_union([polygon, moved]).convex_hull.difference(polygon)

    rooms = [item for item in c03_state["public_rooms"] if "all-weather" not in item["kind"]]
    public_union = unary_union([rect(item["x"], item["y"], item["width"], item["depth"]) for item in rooms])
    winter = unary_union(
        [unary_union([mass_polygon(item), legacy_shadow(item, 26.578)]) for item in c03_state["masses"] if not item["summer_only_shade"]]
    )
    summer = unary_union(
        [unary_union([mass_polygon(item), legacy_shadow(item, 73.458)]) for item in c03_state["masses"]]
    )
    winter_fraction = 1.0 - public_union.intersection(winter).area / public_union.area
    summer_fraction = public_union.intersection(summer).area / public_union.area
    expected = {
        "winter_public_sun_fraction": harness_metrics["winter_public_sun_fraction"],
        "summer_public_shade_fraction": harness_metrics["summer_public_shade_fraction"],
    }
    actual = {"winter_public_sun_fraction": rounded(winter_fraction), "summer_public_shade_fraction": rounded(summer_fraction)}
    return {
        "method": "isolated compatibility reproduction of the prior gross-room due-south noon proxy",
        "expected": expected,
        "actual": actual,
        "pass": actual == expected,
        "not_used_by_detailed_study": True,
    }


def input_receipt(contract: dict[str, Any]) -> dict[str, Any]:
    if not all(path.is_file() for path in (BUILDER_PATH, PACKAGE_MANIFEST, PACKAGE_COMPILER_SNAPSHOT, HARNESS_LATEST)):
        raise RuntimeError("required package/compiler/harness evidence is missing")
    compiler = json.loads(PACKAGE_COMPILER_SNAPSHOT.read_text(encoding="utf-8"))
    if "source_snapshots" in compiler:
        embedded_builder = next(item for item in compiler["source_snapshots"] if item["path"] == "tools/build_shared_floor.py")
    else:
        embedded_builder = compiler.get("source", {})
        if embedded_builder.get("path") != "tools/build_shared_floor.py":
            raise RuntimeError("chunked compiler index lacks the proposal builder identity")
        assembled_parts: list[tuple[int, str]] = []
        for part in compiler.get("parts", []):
            relative = Path(part["path"])
            part_path = PACKAGE / relative
            if (
                not part_path.is_file()
                or part_path.stat().st_size != part.get("size_bytes")
                or file_sha256(part_path) != part.get("sha256")
            ):
                raise RuntimeError(f"compiler source chunk mismatch: {relative}")
            chunk = json.loads(part_path.read_text(encoding="utf-8"))
            assembled_parts.append((int(chunk["part_index"]), chunk["content_utf8_chunk"]))
        assembled = "".join(content for _, content in sorted(assembled_parts))
        assembled_bytes = assembled.encode("utf-8")
        if len(assembled_bytes) != embedded_builder.get("size_bytes") or hashlib.sha256(assembled_bytes).hexdigest() != embedded_builder.get("sha256"):
            raise RuntimeError("chunked compiler source does not reconstruct the declared builder")
    current_builder_sha = file_sha256(BUILDER_PATH)
    if embedded_builder["sha256"] != current_builder_sha:
        raise RuntimeError("competition package is stale relative to the prototype geometry authority")
    harness = json.loads(HARNESS_LATEST.read_text(encoding="utf-8"))
    harness_run_dir = HARNESS_LATEST.parent / harness["run_path"]
    harness_contract_path = harness_run_dir / "run_contract.json"
    harness_receipt_path = harness_run_dir / "build_receipt.json"
    c03_state_path = harness_run_dir / "candidates" / "C03-SHARED-FLOOR" / "design_state.json"
    c03_evaluation_path = harness_run_dir / "candidates" / "C03-SHARED-FLOOR" / "evaluation.json"
    if not all(path.is_file() for path in (harness_contract_path, harness_receipt_path, c03_state_path, c03_evaluation_path)):
        raise RuntimeError("latest harness run is incomplete")
    harness_contract = json.loads(harness_contract_path.read_text(encoding="utf-8"))
    harness_receipt = json.loads(harness_receipt_path.read_text(encoding="utf-8"))
    c03_state = json.loads(c03_state_path.read_text(encoding="utf-8"))
    c03_evaluation = json.loads(c03_evaluation_path.read_text(encoding="utf-8"))
    if file_sha256(harness_receipt_path) != harness["receipt_sha256"]:
        raise RuntimeError("latest harness receipt hash mismatch")
    if harness_contract.get("proposal_builder_sha256") != current_builder_sha:
        raise RuntimeError("latest harness did not evaluate the current proposal builder")
    if c03_evaluation.get("spec_hash") != value_sha256(c03_state):
        raise RuntimeError("C03 design-state hash does not match its evaluation")
    for relative, path in (
        ("candidates/C03-SHARED-FLOOR/design_state.json", c03_state_path),
        ("candidates/C03-SHARED-FLOOR/evaluation.json", c03_evaluation_path),
        ("run_contract.json", harness_contract_path),
    ):
        if harness_receipt["artifact_hashes"].get(relative) != file_sha256(path):
            raise RuntimeError(f"harness artifact receipt mismatch: {relative}")
    snapshot_compare = validate_against_harness_snapshot(c03_state)
    legacy = legacy_compatibility(c03_state, c03_evaluation["metrics"])
    if not legacy["pass"]:
        raise RuntimeError("legacy climate proxy compatibility failed")
    submitted_harness_path = PACKAGE / "visual" / "assets" / "harness-run.json"
    submitted_harness = json.loads(submitted_harness_path.read_text(encoding="utf-8"))
    if submitted_harness.get("run_id") != harness["run_id"] or submitted_harness.get("receipt_sha256") != harness["receipt_sha256"]:
        raise RuntimeError("submitted harness bundle does not point to the latest verified run")
    manifest = json.loads(PACKAGE_MANIFEST.read_text(encoding="utf-8"))
    return {
        "schema_version": "jingzhang-direct-sun-input-receipt-v1",
        "geometry_authority": "tools/build_shared_floor.py::PROTOTYPES",
        "builder_sha256": current_builder_sha,
        "prototype_payload_sha256": value_sha256(PROTOTYPES),
        "package_manifest_sha256": file_sha256(PACKAGE_MANIFEST),
        "package_state": manifest.get("package_state"),
        "embedded_builder_sha256": embedded_builder["sha256"],
        "location_seed": validate_location_seed(),
        "harness_context_only": {
            "path": HARNESS_LATEST.relative_to(WORKSPACE).as_posix(),
            "sha256": file_sha256(HARNESS_LATEST),
            "run_id": harness.get("run_id"),
            "receipt_sha256": harness["receipt_sha256"],
            "c03_design_state_sha256": file_sha256(c03_state_path),
            "c03_spec_hash": c03_evaluation["spec_hash"],
            "submitted_harness_run_sha256": file_sha256(submitted_harness_path),
            "prototype_snapshot_compare": snapshot_compare,
            "legacy_compatibility": legacy,
            "note": "The harness is context/assurance evidence, not the detailed prototype geometry authority.",
        },
        "method_source_sha256": file_sha256(Path(__file__)),
        "dependencies": dependency_versions(),
        "contract_sha256": value_sha256(contract),
    }


def convergence_checks(samples: list[dict[str, Any]], baseline_rows: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    checks = []
    for key in PROTOTYPES:
        half = public_result(evaluate_variant(key, 0, 1, "declared", samples, 0.5))
        double = public_result(evaluate_variant(key, 0, 1, "declared", samples, 2.0))
        one = baseline_rows[key]
        comparisons = {
            "winter_mean_architecture_unshadowed_hours": max(abs(half["winter_mean_architecture_unshadowed_hours"] - one["winter_mean_architecture_unshadowed_hours"]), abs(double["winter_mean_architecture_unshadowed_hours"] - one["winter_mean_architecture_unshadowed_hours"])),
            "winter_area_fraction_architecture_unshadowed_ge_2h": max(abs(half["winter_area_fraction_architecture_unshadowed_ge_2h"] - one["winter_area_fraction_architecture_unshadowed_ge_2h"]), abs(double["winter_area_fraction_architecture_unshadowed_ge_2h"] - one["winter_area_fraction_architecture_unshadowed_ge_2h"])),
            "summer_total_mean_shadow_fraction": max(abs(half["summer_total_mean_shadow_fraction"] - one["summer_total_mean_shadow_fraction"]), abs(double["summer_total_mean_shadow_fraction"] - one["summer_total_mean_shadow_fraction"])),
        }
        passed = comparisons["winter_mean_architecture_unshadowed_hours"] <= 0.10 and comparisons["winter_area_fraction_architecture_unshadowed_ge_2h"] <= 0.02 and comparisons["summer_total_mean_shadow_fraction"] <= 0.02
        checks.append({"prototype": key, "grid_m": [0.5, 1.0, 2.0], "max_absolute_differences": {name: rounded(value) for name, value in comparisons.items()}, "pass": passed})
    return checks


def method_markdown() -> str:
    return """# Прямое солнце и геометрическая тень: метод v1.1

Этот расчёт проверяет точную концептуальную геометрию трёх архитектурных типов,
из которой собраны конкурсные планы и схемы. Положение солнца рассчитывается
реализацией NREL SPA в pvlib каждые 30 минут: зимой 21 декабря с 09:00 до
15:00, летом 21 июня и 21 июля с 10:00 до 17:00.

Проверяются пять поворотов от −15° до +15°, три масштаба высот зданий
80/100/120% и четыре состояния деревьев. Зимнее солнце считается без
неподтверждённого вклада крон. Тень разделена на четыре независимых слоя:
здания; постоянные горизонтальные кровли с заданной отметкой 4,2 м; летние
раздвижные кассеты, которые принудительно отсутствуют в зимней маске; и
сценарный вклад крон. Отдельно показано плановое погодное укрытие — оно не
считается солнечной тенью само по себе.

Рецепторы различаются по архитектурному типу: поле испытаний; три разных
двора; четыре наружных подхода к городскому залу. Крытый центральный зал
исключён из наружного показателя, поэтому он не улучшает результат искусственно.

Высота 4,2 м и сезонный режим — авторские цели концепции, а не доказательство
конструктивной, ветровой или эксплуатационной реализуемости. Это не юридический
расчёт инсоляции, не daylight, не энергетическая модель и не UTCI/MRT. Нет
официальной границы, окружающей застройки, рельефа, облачности, отражений и
подтверждённых пород деревьев. После официальной перепривязки, конструктивной
и эксплуатационной проверки расчёт должен быть выполнен заново.
"""


def _assert_safe_output_root(output_root: Path) -> Path:
    resolved = output_root.expanduser().resolve()
    forbidden = (PACKAGE.resolve(), (WORKSPACE / "haidian-open-call").resolve())
    if any(resolved == root or root in resolved.parents for root in forbidden):
        raise RuntimeError("direct-sun outputs may not be written inside the competition repository/package")
    if resolved in {Path("/").resolve(), Path.home().resolve(), WORKSPACE.resolve()}:
        raise RuntimeError("direct-sun output root is too broad")
    return resolved


def _verify_existing_run(run_dir: Path, expected_receipt: dict[str, Any]) -> None:
    receipt_path = run_dir / "build-receipt.json"
    if not receipt_path.is_file():
        raise RuntimeError("existing immutable run lacks its receipt")
    existing = json.loads(receipt_path.read_text(encoding="utf-8"))
    if existing != expected_receipt:
        raise RuntimeError("non-deterministic output for existing run id")
    for name, record in existing["artifact_hashes"].items():
        artifact = run_dir / name
        if not artifact.is_file() or artifact.stat().st_size != record["size_bytes"] or file_sha256(artifact) != record["sha256"]:
            raise RuntimeError(f"existing immutable artifact failed verification: {name}")


def build_run(output_root: Path = DEFAULT_OUTPUT_ROOT, grid_spacing_m: float = 1.0, created_at: str = EVIDENCE_EPOCH) -> dict[str, Any]:
    output_root = _assert_safe_output_root(output_root)
    contract = make_contract(grid_spacing_m, created_at)
    receipt = input_receipt(contract)
    samples = solar_samples(contract)
    run_material = {"contract": contract, "input_receipt": receipt}
    run_id = f"direct-sun-{value_sha256(run_material)[:12]}"
    output_root.mkdir(parents=True, exist_ok=True)
    runs_root = output_root / "runs"
    runs_root.mkdir(exist_ok=True)
    run_dir = runs_root / run_id
    temp_dir = Path(tempfile.mkdtemp(prefix=f".{run_id}-", dir=output_root))
    try:
        write_json(temp_dir / "run-contract.json", contract)
        write_json(temp_dir / "input-receipt.json", receipt)
        write_csv(temp_dir / "time-samples.csv", samples, ["window_id", "season", "timestamp", "apparent_elevation_deg", "elevation_deg", "azimuth_deg", "interval_hours"])

        rows: list[dict[str, Any]] = []
        zone_rows: list[dict[str, Any]] = []
        spatial_baselines: dict[str, dict[str, Any]] = {}
        for key, rotation, height_scale, tree_state in variant_specs():
            is_spatial_baseline = rotation == 0 and height_scale == 1 and tree_state == "declared"
            result = evaluate_variant(key, rotation, height_scale, tree_state, samples, grid_spacing_m, return_spatial=is_spatial_baseline)
            if is_spatial_baseline:
                spatial_baselines[key] = result
            public = public_result(result)
            zones = public.pop("zone_metrics")
            rows.append(public)
            for zone_name, metrics in zones.items():
                zone_rows.append({"variant_id": public["variant_id"], "prototype": key, "zone": zone_name, **metrics})

        summary = summarize(rows)
        baseline_rows = {
            key: next(row for row in rows if row["prototype"] == key and row["rotation_deg"] == 0 and row["height_scale"] == 1 and row["tree_state"] == "declared")
            for key in PROTOTYPES
        }
        convergence = convergence_checks(samples, baseline_rows)
        no_tree_exact = all(
            abs(row["summer_total_mean_shadow_fraction"] - row["summer_architecture_mean_shadow_fraction"]) <= 1e-9
            for row in rows if row["tree_state"] == "none"
        )
        seasonal_roofs_absent_in_winter = all(row["winter_hot_season_roof_active_count"] == 0 for row in rows)
        dx_south, dy_south = shadow_vector(10, 45, 180)
        dx_east, dy_east = shadow_vector(10, 45, 90)
        dx_west, dy_west = shadow_vector(10, 45, 270)
        checks = {
            "schema_version": "jingzhang-direct-sun-checks-v1",
            "pass": all(item["pass"] for item in convergence) and no_tree_exact and seasonal_roofs_absent_in_winter,
            "sample_count": {"actual": len(samples), "expected": 40, "pass": len(samples) == 40},
            "variant_count": {"actual": len(rows), "expected": 180, "pass": len(rows) == 180},
            "prototype_count": {"actual": len(PROTOTYPES), "expected": 3, "pass": len(PROTOTYPES) == 3},
            "no_tree_total_equals_architecture": {"pass": no_tree_exact},
            "hot_season_retractable_roofs_absent_in_winter": {"pass": seasonal_roofs_absent_in_winter},
            "analytic_10m_45deg_south": {"dx_m": rounded(dx_south), "dy_m": rounded(dy_south), "pass": abs(dx_south) < 1e-9 and abs(dy_south - 10) < 1e-9},
            "east_sun_casts_west": {"dx_m": rounded(dx_east), "dy_m": rounded(dy_east), "pass": dx_east < 0 and abs(dy_east) < 1e-9},
            "west_sun_casts_east": {"dx_m": rounded(dx_west), "dy_m": rounded(dy_west), "pass": dx_west > 0 and abs(dy_west) < 1e-9},
            "grid_convergence": convergence,
            "claim_boundary": contract["claim_boundary"],
        }
        checks["pass"] = checks["pass"] and all(value.get("pass", True) for key, value in checks.items() if isinstance(value, dict) and key != "claim_boundary")

        variant_fields = [key for key in rows[0] if key != "zone_metrics"]
        zone_fields = list(zone_rows[0])
        write_csv(temp_dir / "variant-matrix.csv", rows, variant_fields)
        write_csv(temp_dir / "zone-matrix.csv", zone_rows, zone_fields)
        write_json(temp_dir / "metrics.json", {"schema_version": "jingzhang-direct-sun-metrics-v1", "run_id": run_id, "summary": summary, "claim_boundary": contract["claim_boundary"]})
        write_json(temp_dir / "checks.json", checks)

        receptor_features = []
        for key in PROTOTYPES:
            for zone_name, geometry in receptor_zones(key).items():
                receptor_features.append({"type": "Feature", "id": f"{key}-{zone_name}", "properties": {"prototype": key, "zone": zone_name, "receptor_kind": "activity_area", "geometry_role": "concept_stage_climate_receptor"}, "geometry": mapping(geometry)})
            for zone_name, geometry in route_receptor_zones(key).items():
                receptor_features.append({"type": "Feature", "id": f"{key}-{zone_name}", "properties": {"prototype": key, "zone": zone_name, "receptor_kind": "human_route", "geometry_role": "concept_stage_climate_receptor"}, "geometry": mapping(geometry)})
        write_json(temp_dir / "receptors.geojson", {"type": "FeatureCollection", "name": "jingzhang_direct_sun_receptors", "features": receptor_features})
        (temp_dir / "method.ru.md").write_text(method_markdown().rstrip() + "\n", encoding="utf-8")
        plot_sensitivity(rows, temp_dir / "climate-sensitivity.png")
        plot_spatial(spatial_baselines, temp_dir / "climate-spatial.png")

        artifact_hashes = {
            path.name: {"sha256": file_sha256(path), "size_bytes": path.stat().st_size}
            for path in sorted(temp_dir.iterdir())
            if path.is_file()
        }
        build_receipt = {
            "schema_version": "jingzhang-direct-sun-build-receipt-v1",
            "run_id": run_id,
            "status": "pass" if checks["pass"] else "fail",
            "contract_sha256": value_sha256(contract),
            "input_receipt_sha256": value_sha256(receipt),
            "summary_sha256": value_sha256(summary),
            "artifact_hashes": artifact_hashes,
        }
        write_json(temp_dir / "build-receipt.json", build_receipt)
        if not checks["pass"]:
            raise RuntimeError(f"direct-sun run failed checks; inspect {temp_dir / 'checks.json'}")

        if run_dir.exists():
            _verify_existing_run(run_dir, build_receipt)
            shutil.rmtree(temp_dir)
        else:
            os.replace(temp_dir, run_dir)
        latest = {
            "schema_version": "jingzhang-direct-sun-latest-v1",
            "run_id": run_id,
            "run_path": run_dir.relative_to(WORKSPACE).as_posix(),
            "build_receipt_sha256": file_sha256(run_dir / "build-receipt.json"),
            "prototype_payload_sha256": receipt["prototype_payload_sha256"],
            "status": "pass",
        }
        latest_tmp = output_root / ".latest.json.tmp"
        write_json(latest_tmp, latest)
        os.replace(latest_tmp, output_root / "latest.json")
        return {"run_id": run_id, "run_dir": str(run_dir), "latest": latest, "summary": summary}
    except Exception:
        if temp_dir.exists() and not any(temp_dir.iterdir()):
            temp_dir.rmdir()
        raise


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-root", type=Path, default=DEFAULT_OUTPUT_ROOT)
    parser.add_argument("--grid-spacing-m", type=float, default=1.0)
    parser.add_argument("--created-at", default=EVIDENCE_EPOCH)
    args = parser.parse_args()
    result = build_run(args.output_root, args.grid_spacing_m, args.created_at)
    print(json.dumps({"run_id": result["run_id"], "run_dir": result["run_dir"], "status": result["latest"]["status"]}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

from __future__ import annotations

import json
import tempfile
import unittest
from pathlib import Path

from tools.run_shared_floor_changeover import (
    CLAIM_BOUNDARY,
    FIXTURE_KINDS,
    INJECTED_REGRESSIONS,
    PROMOTION_KEYS,
    TOPOLOGY_SPECS,
    build_contracts,
    build_run,
    build_verification,
    sha256_file,
    sha256_value,
)


def read_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


class SharedFloorChangeoverTests(unittest.TestCase):
    def setUp(self) -> None:
        self.contracts = build_contracts()
        self.verification = build_verification(self.contracts)

    def test_exact_contract_fixture_and_topology_counts(self) -> None:
        self.assertEqual(
            [contract["contract_id"] for contract in self.contracts],
            [f"AI{number:02d}" for number in range(1, 13)],
        )
        self.assertEqual(len(TOPOLOGY_SPECS), 3)
        self.assertEqual(len(self.contracts), 12)
        self.assertEqual(
            sum(len(contract["fixtures"]) for contract in self.contracts), 36
        )
        self.assertEqual(len(self.verification["delta_receipts"]), 36)
        self.assertEqual(
            self.verification["coverage"]["contracts_per_site_topology"],
            {"proof-yard": 4, "origin-cloister": 4, "exchange-hall": 4},
        )

    def test_every_contract_has_fixture_and_control_coverage(self) -> None:
        for contract in self.contracts:
            self.assertEqual(
                {fixture["kind"] for fixture in contract["fixtures"]},
                set(FIXTURE_KINDS),
            )
            self.assertTrue(contract["permanent_h_path"]["available"])
            self.assertTrue(
                contract["permanent_h_path"]["cannot_be_removed_by_model_swap"]
            )
            self.assertFalse(contract["rollback_policy"]["default_allow"])
            self.assertFalse(contract["rollback_policy"]["B_may_disable_A_or_H"])
            self.assertEqual(
                tuple(contract["promotion_policy"]["required_independent_keys"]),
                PROMOTION_KEYS,
            )
            self.assertEqual(contract["promotion_policy"]["minimum_key_count"], 2)

        coverage = self.verification["coverage"]
        self.assertEqual(coverage["contracts_with_all_three_fixture_kinds"], 12)
        self.assertEqual(coverage["contracts_with_permanent_H_path"], 12)
        self.assertEqual(coverage["contracts_with_two_key_policy"], 12)
        self.assertEqual(coverage["contracts_with_deny_by_default_rollback"], 12)

    def test_eight_safe_eligible_four_regressions_held_and_none_promoted(self) -> None:
        summary = self.verification["summary"]
        self.assertEqual(summary["safe_candidate_count"], 8)
        self.assertEqual(summary["unsafe_candidate_count"], 4)
        self.assertEqual(summary["eligible_for_live_shadow_count"], 8)
        self.assertEqual(summary["held_contract_regression_count"], 4)
        self.assertEqual(summary["unsafe_eligible_count"], 0)
        self.assertEqual(summary["unsafe_promotion_count"], 0)
        self.assertEqual(summary["promotion_executed_count"], 0)
        self.assertEqual(self.verification["status"], "pass")

        by_id = {
            result["contract_id"]: result
            for result in self.verification["contract_results"]
        }
        self.assertEqual(
            {
                contract_id
                for contract_id, result in by_id.items()
                if result["candidate_state"] == "held_contract_regression"
            },
            set(INJECTED_REGRESSIONS),
        )
        for contract_id, result in by_id.items():
            self.assertFalse(result["promotion_executed"])
            self.assertFalse(result["unsafe_candidate_promoted"])
            if contract_id in INJECTED_REGRESSIONS:
                self.assertFalse(result["two_key_gate_passed"])
                self.assertFalse(
                    result["promotion_keys"]["rights_and_safety_steward"]["granted"]
                )
            else:
                self.assertTrue(result["two_key_gate_passed"])

    def test_contract_and_delta_receipt_hashes_are_content_addressed(self) -> None:
        for contract in self.contracts:
            unhashed = {
                key: value
                for key, value in contract.items()
                if key != "contract_sha256"
            }
            self.assertEqual(contract["contract_sha256"], sha256_value(unhashed))

        for receipt in self.verification["delta_receipts"]:
            unhashed = {
                key: value
                for key, value in receipt.items()
                if key not in {"receipt_sha256", "receipt_address"}
            }
            self.assertEqual(receipt["receipt_sha256"], sha256_value(unhashed))
            self.assertEqual(
                receipt["receipt_address"], f"sha256:{receipt['receipt_sha256']}"
            )

    def test_materialized_receipts_and_latest_pointer_verify(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            output = Path(temp_dir)
            result = build_run(output)
            run_dir = Path(result["run_dir"])
            build_receipt = read_json(run_dir / "build_receipt.json")
            latest = read_json(output / "latest.json")

            receipt_files = sorted((run_dir / "delta_receipts").glob("*.json"))
            self.assertEqual(len(receipt_files), 36)
            for receipt_path in receipt_files:
                receipt = read_json(receipt_path)
                self.assertEqual(receipt_path.stem, receipt["receipt_sha256"])

            for relative_path, digest in build_receipt["artifact_sha256"].items():
                self.assertEqual(sha256_file(run_dir / relative_path), digest)
            self.assertEqual(latest["run_id"], result["run_id"])
            self.assertEqual(
                latest["build_receipt_sha256"],
                sha256_file(run_dir / "build_receipt.json"),
            )

    def test_equivalent_epoch_is_deterministic(self) -> None:
        with tempfile.TemporaryDirectory() as first, tempfile.TemporaryDirectory() as second:
            left = build_run(Path(first), "2026-08-20T00:00:00Z")
            right = build_run(Path(second), "2026-08-20T03:00:00+03:00")
            self.assertEqual(left["run_id"], right["run_id"])
            left_dir = Path(left["run_dir"])
            right_dir = Path(right["run_dir"])
            for relative_path in (
                "run_contract.json",
                "topologies.json",
                "contracts.json",
                "verification.json",
                "build_receipt.json",
            ):
                self.assertEqual(
                    (left_dir / relative_path).read_bytes(),
                    (right_dir / relative_path).read_bytes(),
                )

    def test_claim_boundary_forbids_performance_inference(self) -> None:
        self.assertEqual(CLAIM_BOUNDARY["live_model_runs"], 0)
        self.assertEqual(CLAIM_BOUNDARY["live_user_sessions"], 0)
        self.assertEqual(CLAIM_BOUNDARY["field_trials"], 0)
        self.assertEqual(CLAIM_BOUNDARY["field_performance_observations"], 0)
        self.assertFalse(CLAIM_BOUNDARY["deployment_or_promotion_executed"])
        self.assertEqual(self.verification["claim_boundary"], CLAIM_BOUNDARY)


if __name__ == "__main__":
    unittest.main()

#!/usr/bin/env python3
"""Run the local Shared Floor semantic-routing shadow witness.

This design-time benchmark makes one local Ollama embedding call for a fixed
set of three topology descriptions and 36 hypothetical fixtures.  The
participant-authored topology label is A/reference, B is the embedding-based
candidate, and a deterministic H gate holds every hard-stop fixture.  B never
acts, deploys, or becomes promoted.

The benchmark does not involve a live public service, a real user, site
operations, personal data, chain-of-thought, or independent field truth.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import shutil
