def canonical_json(value: Any) -> bytes:
    """Return the single byte representation used by every content hash."""

    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def sha256_value(value: Any) -> str:
    return hashlib.sha256(canonical_json(value)).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(canonical_json(value) + b"\n")


def read_json_object(path: Path, label: str) -> dict[str, Any]:
    """Read one required JSON object with a precise fail-closed error."""

    if not path.is_file():
        raise RuntimeError(f"changeover {label} is missing: {path}")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"cannot read changeover {label}: {exc}") from exc
    if not isinstance(value, dict):
        raise RuntimeError(f"changeover {label} must be a JSON object")
    return value


def _is_sha256(value: Any) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(character in "0123456789abcdef" for character in value)
    )


def load_verified_changeover_binding(latest_path: Path) -> dict[str, Any]:
    """Verify and compactly bind the immutable A/B/H changeover authority.

    The semantic benchmark treats the existing changeover contracts as the
    authority for its participant-authored A labels.  Every hash and identity
    check therefore completes before model provenance lookup or embedding.
    """

    latest_path = latest_path.expanduser().resolve()
    latest = read_json_object(latest_path, "latest pointer")
    if latest.get("schema") != "shared-floor-changeover-latest/v1":
        raise RuntimeError("changeover latest pointer schema mismatch")
    run_id = latest.get("run_id")
    run_path = latest.get("run_path")
    if not isinstance(run_id, str) or not run_id:
        raise RuntimeError("changeover latest pointer lacks run_id")
    if run_path != f"runs/{run_id}":
        raise RuntimeError("changeover latest pointer run identity mismatch")

    changeover_root = latest_path.parent
    runs_root = (changeover_root / "runs").resolve()
    run_dir = (changeover_root / run_path).resolve()
    if runs_root not in run_dir.parents:
        raise RuntimeError("changeover latest pointer escapes immutable runs")

    build_receipt_path = run_dir / "build_receipt.json"
    build_receipt = read_json_object(build_receipt_path, "build receipt")
    expected_build_receipt_sha256 = latest.get("build_receipt_sha256")
    if not _is_sha256(expected_build_receipt_sha256):
        raise RuntimeError("changeover latest pointer has invalid build receipt hash")
    if sha256_file(build_receipt_path) != expected_build_receipt_sha256:
        raise RuntimeError("changeover build receipt hash mismatch")
    if (
        build_receipt.get("schema")
        != "shared-floor-changeover-build-receipt/v1"
        or build_receipt.get("run_id") != run_id
        or build_receipt.get("status") != "pass"
    ):
        raise RuntimeError("changeover build receipt identity or status mismatch")

    artifact_hashes = build_receipt.get("artifact_sha256")
    if not isinstance(artifact_hashes, dict):
        raise RuntimeError("changeover build receipt lacks artifact hashes")
    required_artifacts = {
        "run_contract.json",
        "topologies.json",
        "contracts.json",
        "verification.json",
    }
    if not required_artifacts.issubset(artifact_hashes):
        missing = sorted(required_artifacts.difference(artifact_hashes))
        raise RuntimeError(f"changeover build receipt omits artifacts: {missing}")
    for relative, expected_sha256 in sorted(artifact_hashes.items()):
        if not isinstance(relative, str) or not _is_sha256(expected_sha256):
            raise RuntimeError("changeover build receipt has an invalid artifact entry")
        relative_path = Path(relative)
        if relative_path.is_absolute() or ".." in relative_path.parts:
            raise RuntimeError(f"unsafe changeover artifact path: {relative}")
        artifact_path = (run_dir / relative_path).resolve()
        if run_dir not in artifact_path.parents or not artifact_path.is_file():
            raise RuntimeError(f"changeover immutable artifact is missing: {relative}")
        if sha256_file(artifact_path) != expected_sha256:
            raise RuntimeError(f"changeover immutable artifact mismatch: {relative}")

    run_contract_path = run_dir / "run_contract.json"
    topologies_path = run_dir / "topologies.json"
    contracts_path = run_dir / "contracts.json"
    verification_path = run_dir / "verification.json"
    run_contract = read_json_object(run_contract_path, "run contract")
    topologies = read_json_object(topologies_path, "topology set")
    contracts = read_json_object(contracts_path, "contract set")
    verification = read_json_object(verification_path, "verification")
    if run_contract.get("schema") != "shared-floor-changeover-run/v1":
        raise RuntimeError("changeover run contract schema mismatch")
    expected_run_id = (
        f"shared-floor-changeover-{sha256_value(run_contract)[:16]}"
    )
    if run_id != expected_run_id:
        raise RuntimeError("changeover content-addressed run id mismatch")
    if verification.get("status") != "pass":
        raise RuntimeError("changeover verification status is not pass")
    if (
        build_receipt.get("summary") != verification.get("summary")
        or build_receipt.get("coverage") != verification.get("coverage")
    ):
        raise RuntimeError("changeover build receipt does not bind verification")

    contract_set_sha256 = sha256_value(contracts)
    topology_spec_sha256 = sha256_value(topologies)
    if run_contract.get("contract_set_sha256") != contract_set_sha256:
        raise RuntimeError("changeover contract-set hash mismatch")
    if run_contract.get("topology_spec_sha256") != topology_spec_sha256:
        raise RuntimeError("changeover topology-spec hash mismatch")
    if not CHANGEOVER_RUNNER_PATH.is_file():
        raise RuntimeError("changeover runner source is missing")
    if run_contract.get("runner_sha256") != sha256_file(CHANGEOVER_RUNNER_PATH):
        raise RuntimeError("changeover runner source hash mismatch")

    actual_topologies = topologies.get("topologies")
    if not isinstance(actual_topologies, list):
        raise RuntimeError("changeover topology set lacks topologies")
    expected_topology_identity = [
        {
            "site_id": item["site_id"],
            "site_name": item["site_name"],
            "topology_id": item["topology_id"],
        }
        for item in TOPOLOGY_SPECS
    ]
    actual_topology_identity = [
        {
            "site_id": item.get("site_id"),
            "site_name": item.get("site_name"),
            "topology_id": item.get("topology_id"),
        }
        for item in actual_topologies
        if isinstance(item, dict)
    ]
    if actual_topology_identity != expected_topology_identity:
        raise RuntimeError("semantic/changeover topology identity parity mismatch")

    topology_id_by_site = {
        item["site_id"]: item["topology_id"] for item in TOPOLOGY_SPECS
    }
    expected_contract_identity = [
        {
            "contract_id": item["contract_id"],
            "title": item["title"],
            "site_id": item["reference_site_id"],
            "topology_id": topology_id_by_site[item["reference_site_id"]],
        }
        for item in SCENARIO_SPECS
    ]
    actual_contracts = contracts.get("contracts")
    if not isinstance(actual_contracts, list):
        raise RuntimeError("changeover contract set lacks contracts")
    actual_contract_identity: list[dict[str, Any]] = []
    for contract in actual_contracts:
        if not isinstance(contract, dict):
            raise RuntimeError("changeover contract set contains a non-object")
        contract_body = {
            key: value
            for key, value in contract.items()
            if key != "contract_sha256"
        }
        if contract.get("contract_sha256") != sha256_value(contract_body):
            raise RuntimeError(
                f"changeover internal contract hash mismatch: "
                f"{contract.get('contract_id')}"
            )
        actual_contract_identity.append(
            {
                "contract_id": contract.get("contract_id"),
                "title": contract.get("title"),
                "site_id": contract.get("site_id"),
                "topology_id": contract.get("topology_id"),
            }
        )
    if actual_contract_identity != expected_contract_identity:
        raise RuntimeError("semantic/changeover contract identity parity mismatch")

    return {
        "schema": "shared-floor-semantic-changeover-binding/v1",
        "authority": "verified_immutable_changeover_v1_latest",
        "run_id": run_id,
        "latest_pointer_sha256": sha256_file(latest_path),
        "build_receipt_sha256": expected_build_receipt_sha256,
        "run_contract_sha256": sha256_file(run_contract_path),
        "contract_set_sha256": contract_set_sha256,
        "topology_spec_sha256": topology_spec_sha256,
        "contract_count": len(actual_contract_identity),
        "topology_count": len(actual_topology_identity),
        "identity_parity": "AI01-AI12_title_site_topology_exact",
    }


def normalized_created_at(value: str) -> str:
    parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        raise ValueError("--created-at must include a timezone")
    return parsed.astimezone(timezone.utc).isoformat(timespec="seconds").replace(
        "+00:00", "Z"
    )


def _request_json(
    url: str,
    *,
    payload: Mapping[str, Any] | None = None,
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    data = canonical_json(payload) if payload is not None else None
    headers = {"Content-Type": "application/json"} if data is not None else {}
    request = urllib.request.Request(url, data=data, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = json.load(response)
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Ollama request failed for {url}: {exc}") from exc
    if not isinstance(body, dict):
        raise ValueError(f"Ollama returned a non-object response for {url}")
    return body


def default_models_root() -> Path:
    configured = os.environ.get("OLLAMA_MODELS")
    if configured:
        return Path(configured).expanduser().resolve()
    return Path.home() / ".ollama" / "models"


def normalize_local_ollama_endpoint(endpoint: str) -> str:
    """Accept only an unauthenticated HTTP loopback Ollama base URL."""

    if not isinstance(endpoint, str) or not endpoint:
        raise ValueError("Ollama endpoint must be a non-empty loopback URL")
    parsed = urllib.parse.urlsplit(endpoint)
    if parsed.scheme.lower() != "http":
        raise ValueError("Ollama endpoint must use plain HTTP on loopback")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("Ollama endpoint credentials are forbidden")
    host = (parsed.hostname or "").lower()
    if host not in {"127.0.0.1", "localhost", "::1"}:
        raise ValueError("Ollama endpoint must resolve syntactically to loopback")
    if parsed.path not in {"", "/"} or parsed.query or parsed.fragment:
        raise ValueError("Ollama endpoint must be a bare loopback base URL")
    try:
        port = parsed.port
    except ValueError as exc:
        raise ValueError("Ollama endpoint has an invalid port") from exc
    rendered_host = f"[{host}]" if host == "::1" else host
    return f"http://{rendered_host}{f':{port}' if port is not None else ''}"


def verify_model_provenance(
    endpoint: str,
    models_root: Path | None = None,
    verify_blob_bytes: bool = True,
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    """Fail closed unless the exact local BGE-M3 tag and blob are present."""

    endpoint = normalize_local_ollama_endpoint(endpoint)
    tags = _request_json(f"{endpoint}/api/tags", timeout=timeout)
    version = _request_json(f"{endpoint}/api/version", timeout=timeout)
    candidates = [
        item
        for item in tags.get("models", [])
        if isinstance(item, dict)
        and (item.get("name") == MODEL_NAME or item.get("model") == MODEL_NAME)
    ]
    if len(candidates) != 1:
        raise RuntimeError(
            f"expected exactly one local {MODEL_NAME} tag, found {len(candidates)}"
        )
    tag = candidates[0]
    tag_digest = str(tag.get("digest", ""))
    capabilities = tag.get("capabilities", [])
    details = tag.get("details", {}) if isinstance(tag.get("details"), dict) else {}

    root = (models_root or default_models_root()).resolve()
    manifest_relative = Path(
        "manifests/registry.ollama.ai/library/bge-m3/latest"
    )
    manifest_path = root / manifest_relative
    if not manifest_path.is_file():
        raise RuntimeError(f"local Ollama manifest is missing: {manifest_path}")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"cannot read local Ollama manifest: {exc}") from exc
    layers = manifest.get("layers", []) if isinstance(manifest, dict) else []
    model_layers = [
        layer
        for layer in layers
        if isinstance(layer, dict)
        and layer.get("mediaType") == "application/vnd.ollama.image.model"
    ]
    if len(model_layers) != 1:
        raise RuntimeError(
            f"expected one model layer in local manifest, found {len(model_layers)}"
        )
    model_layer_digest = str(model_layers[0].get("digest", ""))
    blob_path = root / "blobs" / MODEL_BLOB_FILENAME
    blob_exists = blob_path.is_file()
    blob_byte_sha256 = sha256_file(blob_path) if blob_exists and verify_blob_bytes else None
    manifest_file_sha256 = sha256_file(manifest_path)

    checks = {
        "model_name_exact": tag.get("name", tag.get("model")) == MODEL_NAME,
        "registry_digest_exact": tag_digest == MODEL_REGISTRY_DIGEST,
        "manifest_file_digest_exact": manifest_file_sha256
        == MODEL_REGISTRY_DIGEST,
        "single_embedding_capability": capabilities == ["embedding"],
        "embedding_dimension_exact": details.get("embedding_length")
        == MODEL_EMBEDDING_DIMENSION,
        "model_layer_digest_exact": model_layer_digest
        == f"sha256:{MODEL_BLOB_SHA256}",
        "local_blob_present": blob_exists,
        "local_blob_bytes_verified": verify_blob_bytes,
        "local_blob_byte_digest_exact": blob_byte_sha256 == MODEL_BLOB_SHA256,
    }
    status = "pass" if all(checks.values()) else "fail"
    provenance = {
        "schema": "shared-floor-semantic-model-provenance/v1",
        "status": status,
        "model_name": MODEL_NAME,
        "registry_digest": MODEL_REGISTRY_DIGEST,
        "registry_digest_address": f"sha256:{MODEL_REGISTRY_DIGEST}",
        "local_manifest_relative_path": manifest_relative.as_posix(),
        "local_manifest_file_sha256": manifest_file_sha256,
        "local_model_blob_filename": MODEL_BLOB_FILENAME,
        "local_model_blob_sha256": MODEL_BLOB_SHA256,
        "local_model_blob_address": f"sha256:{MODEL_BLOB_SHA256}",
        "ollama_version": version.get("version"),
        "endpoint": {
            "normalized_base_url": endpoint,
            "network_scope": "syntactic_loopback_only",
            "credentials_query_fragment_forbidden": True,
        },
        "declared_embedding_dimension": details.get("embedding_length"),
        "model_size_bytes": tag.get("size"),
        "checks": checks,
        "license_boundary": {
            "local_runtime_use_only": True,
            "weights_redistributed": False,
            "license_claim_derived_from_runtime_metadata": False,
        },
    }
    if status != "pass":
        failed = sorted(key for key, passed in checks.items() if not passed)
        raise RuntimeError(f"exact-model provenance verification failed: {failed}")
    return provenance


def call_ollama_embeddings(
    endpoint: str,
    model_name: str,
    inputs: Sequence[str],
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    """Make the benchmark's single batched local embedding request."""

    endpoint = normalize_local_ollama_endpoint(endpoint)
    return _request_json(
        f"{endpoint}/api/embed",
        payload={
            "model": model_name,
            "input": list(inputs),
            "truncate": False,
            "keep_alive": "0",
        },
        timeout=timeout,
    )


def build_fixtures() -> list[dict[str, Any]]:
    topology_ids = set(TOPOLOGY_ORDER)
    fixtures: list[dict[str, Any]] = []
    for scenario in SCENARIO_SPECS:
        reference_site_id = scenario["reference_site_id"]
        if reference_site_id not in topology_ids:
            raise ValueError(f"unknown reference topology: {reference_site_id}")
        for kind in FIXTURE_KINDS:
            body = {
                "fixture_id": f"{scenario['contract_id']}-{kind}",
                "contract_id": scenario["contract_id"],
                "scenario_title": scenario["title"],
                "fixture_kind": kind,
                "input_text": scenario["texts"][kind],
                "A_reference": {
                    "site_id": reference_site_id,
                    "authority": "participant_authored_contract_topology_label",
                    "independent_ground_truth": False,
                },
                "H_hard_stop_expected": kind == "hard-stop",
                "input_data_class": "fixed_hypothetical_text_without_personal_data",
            }
            fixture = dict(body)
            fixture["fixture_sha256"] = sha256_value(body)
            fixtures.append(fixture)
    return fixtures


def _validate_embeddings(
    response: Mapping[str, Any], expected_count: int
) -> list[list[float]]:
    embeddings = response.get("embeddings")
    if not isinstance(embeddings, list) or len(embeddings) != expected_count:
        observed = len(embeddings) if isinstance(embeddings, list) else None
        raise ValueError(
            f"expected {expected_count} embeddings from one batch, got {observed}"
        )
    normalized: list[list[float]] = []
    for index, embedding in enumerate(embeddings):
        if not isinstance(embedding, list) or len(embedding) != MODEL_EMBEDDING_DIMENSION:
            dimension = len(embedding) if isinstance(embedding, list) else None
            raise ValueError(
                f"embedding {index} has dimension {dimension}; "
                f"expected {MODEL_EMBEDDING_DIMENSION}"
            )
        vector = [float(value) for value in embedding]
        if not all(math.isfinite(value) for value in vector):
            raise ValueError(f"embedding {index} contains a non-finite value")
        if not any(value != 0.0 for value in vector):
            raise ValueError(f"embedding {index} is a zero vector")
        normalized.append(vector)
    return normalized


def cosine_similarity(left: Sequence[float], right: Sequence[float]) -> float:
    numerator = math.fsum(a * b for a, b in zip(left, right))
    left_norm = math.sqrt(math.fsum(value * value for value in left))
    right_norm = math.sqrt(math.fsum(value * value for value in right))
    if left_norm == 0.0 or right_norm == 0.0:
        raise ValueError("cosine similarity is undefined for a zero vector")
    return numerator / (left_norm * right_norm)


def build_predictions(
    fixtures: Sequence[dict[str, Any]],
    embeddings: Sequence[Sequence[float]],
    run_contract_sha256: str,
) -> list[dict[str, Any]]:
    topology_vectors = embeddings[: len(TOPOLOGY_SPECS)]
    fixture_vectors = embeddings[len(TOPOLOGY_SPECS) :]
    predictions: list[dict[str, Any]] = []
    for fixture, fixture_vector in zip(fixtures, fixture_vectors):
        raw_scores = {
            site_id: cosine_similarity(fixture_vector, topology_vector)
            for site_id, topology_vector in zip(TOPOLOGY_ORDER, topology_vectors)
        }
        candidate_site_id = max(
            TOPOLOGY_ORDER,
            key=lambda site_id: (raw_scores[site_id], -TOPOLOGY_ORDER.index(site_id)),
        )
        ranked = sorted(
            TOPOLOGY_ORDER,
            key=lambda site_id: (-raw_scores[site_id], TOPOLOGY_ORDER.index(site_id)),
        )
        scores = {site_id: round(raw_scores[site_id], 12) for site_id in TOPOLOGY_ORDER}
        hard_stop = bool(fixture["H_hard_stop_expected"])
        reference_site_id = fixture["A_reference"]["site_id"]
        body = {
            "schema": "shared-floor-semantic-prediction-receipt/v1",
            "run_contract_sha256": run_contract_sha256,
            "fixture_id": fixture["fixture_id"],
            "fixture_sha256": fixture["fixture_sha256"],
            "fixture_kind": fixture["fixture_kind"],
            "A_reference": fixture["A_reference"],
            "B_candidate": {
                "site_id": candidate_site_id,
                "cosine_scores": scores,
                "top_two_margin": round(
                    raw_scores[ranked[0]] - raw_scores[ranked[1]], 12
                ),
                "agrees_with_A_reference": candidate_site_id == reference_site_id,
                "shadow_only": True,
                "allowed_to_act_or_publish": False,
            },
            "H_safety": {
                "hard_stop_detected_from_fixed_fixture_contract": hard_stop,
                "deterministic_hold_engaged": hard_stop,
                "superseded_B_candidate": hard_stop,
                "selected_route": (
                    "H_deterministic_hold"
                    if hard_stop
                    else "no_operational_route_shadow_only"
                ),
            },
            "decision": {
                "promotion_executed": False,
                "deployment_executed": False,
                "field_action_executed": False,
            },
            "claim_boundary": CLAIM_BOUNDARY,
        }
        receipt = dict(body)
        receipt_sha256 = sha256_value(body)
        receipt["receipt_sha256"] = receipt_sha256
        receipt["receipt_address"] = f"sha256:{receipt_sha256}"
        predictions.append(receipt)
    return predictions


def build_verification(
    fixtures: Sequence[dict[str, Any]],
    predictions: Sequence[dict[str, Any]],
    provenance: Mapping[str, Any],
    model_api_call_count: int,
) -> dict[str, Any]:
    by_fixture = {item["fixture_id"]: item for item in fixtures}
    agreement_count = sum(
        item["B_candidate"]["agrees_with_A_reference"] for item in predictions
    )
    non_hard_stop = [
        item for item in predictions if item["fixture_kind"] != "hard-stop"
    ]
    hard_stops = [item for item in predictions if item["fixture_kind"] == "hard-stop"]
    disagreements = [
        item
        for item in predictions
        if not item["B_candidate"]["agrees_with_A_reference"]
    ]
    origin_non_hard_stop_disagreements = [
        item
        for item in disagreements
        if item["fixture_kind"] != "hard-stop"
        and by_fixture[item["fixture_id"]]["A_reference"]["site_id"]
        == "origin-cloister"
    ]
    summary = {
        "topology_count": len(TOPOLOGY_SPECS),
        "scenario_count": len(SCENARIO_SPECS),
        "fixture_count": len(fixtures),
        "model_api_call_count": model_api_call_count,
        "embedding_input_count": len(TOPOLOGY_SPECS) + len(fixtures),
        "topology_agreement_count": agreement_count,
        "topology_agreement_ratio": f"{agreement_count}/{len(predictions)}",
        "non_hard_stop_fixture_count": len(non_hard_stop),
        "non_hard_stop_agreement_count": sum(
            item["B_candidate"]["agrees_with_A_reference"]
            for item in non_hard_stop
        ),
        "non_hard_stop_agreement_ratio": (
            f"{sum(item['B_candidate']['agrees_with_A_reference'] for item in non_hard_stop)}"
            f"/{len(non_hard_stop)}"
        ),
        "disagreement_count": len(disagreements),
        "origin_non_hard_stop_disagreement_count": len(
            origin_non_hard_stop_disagreements
        ),
        "hard_stop_fixture_count": len(hard_stops),
        "hard_stop_hold_count": sum(
            item["H_safety"]["deterministic_hold_engaged"] for item in hard_stops
        ),
        "hard_stop_semantic_disagreement_count": sum(
            not item["B_candidate"]["agrees_with_A_reference"]
            for item in hard_stops
        ),
        "promotion_executed_count": sum(
            item["decision"]["promotion_executed"] for item in predictions
        ),
    }
    observed_result = {key: summary[key] for key in EXPECTED_RESULT}
    confusion_matrix = {
        reference_site: {
            candidate_site: sum(
                by_fixture[item["fixture_id"]]["A_reference"]["site_id"]
                == reference_site
                and item["B_candidate"]["site_id"] == candidate_site
                for item in predictions
            )
            for candidate_site in TOPOLOGY_ORDER
        }
        for reference_site in TOPOLOGY_ORDER
    }
    checks = {
        "exact_model_provenance_passed": provenance.get("status") == "pass",
        "one_batched_local_model_call": model_api_call_count == 1,
        "fixed_12_by_3_fixture_set": len(SCENARIO_SPECS) == 12
        and len(fixtures) == 36,
        "observed_result_matches_frozen_witness": observed_result == EXPECTED_RESULT,
        "every_hard_stop_held_by_deterministic_H": all(
            item["H_safety"]["deterministic_hold_engaged"]
            and item["H_safety"]["superseded_B_candidate"]
            for item in hard_stops
        ),
        "B_remained_shadow_only": all(
            item["B_candidate"]["shadow_only"]
            and not item["B_candidate"]["allowed_to_act_or_publish"]
            for item in predictions
        ),
        "zero_promotion_deployment_or_field_action": all(
            not item["decision"]["promotion_executed"]
            and not item["decision"]["deployment_executed"]
            and not item["decision"]["field_action_executed"]
            for item in predictions
        ),
        "reference_labels_not_represented_as_independent_truth": all(
            not item["A_reference"]["independent_ground_truth"]
            for item in fixtures
        ),
    }
    return {
        "schema": "shared-floor-semantic-verification/v1",
        "method_version": METHOD_VERSION,
        "status": "pass" if all(checks.values()) else "fail",
        "checks": checks,
        "summary": summary,
        "expected_result": EXPECTED_RESULT,
        "observed_result": observed_result,
        "confusion_matrix_A_reference_by_B_candidate": confusion_matrix,
        "disagreement_fixture_ids": [item["fixture_id"] for item in disagreements],
        "origin_non_hard_stop_disagreement_fixture_ids": [
            item["fixture_id"] for item in origin_non_hard_stop_disagreements
        ],
        "interpretation": {
            "success_metric": "safety_gate_coverage_and_observable_candidate_delta",
            "not_a_success_metric": "maximizing_agreement_with_participant_authored_labels",
            "spatial_design_signal": (
                "All four non-hard-stop disagreements use the Origin Cloister "
                "reference; retain and strengthen its permanent H table and "
                "public difference display."
            ),
        },
        "claim_boundary": CLAIM_BOUNDARY,
    }


def _inference_receipt(
    response: Mapping[str, Any], input_count: int, embedding_dimension: int
) -> dict[str, Any]:
    return {
        "schema": "shared-floor-semantic-inference-receipt/v1",
        "model_name": MODEL_NAME,
        "model_registry_digest": MODEL_REGISTRY_DIGEST,
        "api": "ollama_/api/embed",
        "api_call_count": 1,
        "batch_input_count": input_count,
        "embedding_dimension": embedding_dimension,
        "prompt_eval_count": response.get("prompt_eval_count"),
        "runtime_timing_persisted": False,
        "runtime_timing_reason": "volatile wall-clock observations are excluded from immutable evidence",
        "embeddings_persisted": False,
        "predictions_persisted": True,
        "claim_boundary": CLAIM_BOUNDARY,
    }


def build_run(
    output_root: Path,
    created_at: str = DEFAULT_RUN_CREATED_AT,
    endpoint: str = DEFAULT_OLLAMA_ENDPOINT,
    models_root: Path | None = None,
    verify_blob_bytes: bool = True,
    timeout: float = DEFAULT_TIMEOUT_SECONDS,
    changeover_latest: Path = DEFAULT_CHANGEOVER_LATEST,
    provenance_resolver: ProvenanceResolver = verify_model_provenance,
    embedding_provider: EmbeddingProvider = call_ollama_embeddings,
) -> dict[str, Any]:
    """Execute and materialize one content-addressed immutable witness run."""

    normalized_time = normalized_created_at(created_at)
    endpoint = normalize_local_ollama_endpoint(endpoint)
    fixtures = build_fixtures()
    fixture_set = {
        "schema": "shared-floor-semantic-fixtures/v1",
        "fixture_kinds": list(FIXTURE_KINDS),
        "fixtures": fixtures,
    }
    topologies = {
        "schema": "shared-floor-semantic-topologies/v1",
        "topology_order": list(TOPOLOGY_ORDER),
        "topologies": list(TOPOLOGY_SPECS),
    }
    changeover_binding = load_verified_changeover_binding(changeover_latest)
    provenance = provenance_resolver(
        endpoint, models_root, verify_blob_bytes, timeout
    )
    if provenance.get("status") != "pass":
        raise RuntimeError("model provenance resolver did not return pass")

    run_contract = {
        "schema": "shared-floor-semantic-run-contract/v2",
        "method_version": METHOD_VERSION,
        "created_at": normalized_time,
        "runner_sha256": sha256_file(RUNNER_PATH),
        "topology_set_sha256": sha256_value(topologies),
        "fixture_set_sha256": sha256_value(fixture_set),
        "changeover_binding": changeover_binding,
        "roles": ROLE_CONTRACT,
        "method": {
            "embedding_api": "one_local_ollama_/api/embed_batch",
            "normalized_endpoint": endpoint,
            "endpoint_policy": "http_loopback_only_no_credentials_query_fragment_or_path",
            "similarity": "cosine_similarity",
            "candidate_selection": "top_1_of_three_fixed_topology_descriptors",
            "tie_break_order": list(TOPOLOGY_ORDER),
            "model_api_call_count": 1,
            "embedding_input_count": len(TOPOLOGY_SPECS) + len(fixtures),
            "embedding_vectors_persisted": False,
        },
        "model_provenance": provenance,
        "claim_boundary": CLAIM_BOUNDARY,
    }
    run_contract_sha256 = sha256_value(run_contract)
    inputs = [item["descriptor"] for item in TOPOLOGY_SPECS] + [
        item["input_text"] for item in fixtures
    ]
    response = embedding_provider(endpoint, MODEL_NAME, inputs, timeout)
    embeddings = _validate_embeddings(response, len(inputs))
    predictions = build_predictions(fixtures, embeddings, run_contract_sha256)
    prediction_set = {
        "schema": "shared-floor-semantic-predictions/v1",
        "run_contract_sha256": run_contract_sha256,
        "prediction_count": len(predictions),
        "predictions": predictions,
    }
    inference_receipt = _inference_receipt(
        response, len(inputs), len(embeddings[0])
    )
    verification = build_verification(fixtures, predictions, provenance, 1)
    address_material = {
        "run_contract_sha256": run_contract_sha256,
        "topologies_sha256": sha256_value(topologies),
        "fixtures_sha256": sha256_value(fixture_set),
        "predictions_sha256": sha256_value(prediction_set),
        "inference_receipt_sha256": sha256_value(inference_receipt),
        "verification_sha256": sha256_value(verification),
    }
    run_id = f"shared-floor-semantic-{sha256_value(address_material)[:16]}"
    output_root = output_root.resolve()
    runs_root = output_root / "runs"
    run_dir = runs_root / run_id
    if run_dir.exists():
        raise FileExistsError(f"immutable run already exists: {run_dir}")
    runs_root.mkdir(parents=True, exist_ok=True)
    stage_dir = Path(tempfile.mkdtemp(prefix=".semantic-witness-", dir=runs_root))
    try:
        write_json(stage_dir / "run_contract.json", run_contract)
        write_json(stage_dir / "topologies.json", topologies)
        write_json(stage_dir / "fixtures.json", fixture_set)
        write_json(stage_dir / "predictions.json", prediction_set)
        write_json(stage_dir / "inference_receipt.json", inference_receipt)
        write_json(stage_dir / "verification.json", verification)
        for receipt in predictions:
            write_json(
                stage_dir
                / "prediction_receipts"
                / f"{receipt['receipt_sha256']}.json",
                receipt,
            )
        artifact_hashes = {
            path.relative_to(stage_dir).as_posix(): sha256_file(path)
            for path in sorted(stage_dir.rglob("*.json"))
        }
        build_receipt = {
            "schema": "shared-floor-semantic-build-receipt/v1",
            "method_version": METHOD_VERSION,
            "run_id": run_id,
            "run_address_material": address_material,
            "created_at": normalized_time,
            "status": verification["status"],
            "summary": verification["summary"],
            "model_provenance": provenance,
            "claim_boundary": CLAIM_BOUNDARY,
            "artifact_sha256": artifact_hashes,
        }
        build_receipt_path = stage_dir / "build_receipt.json"
        write_json(build_receipt_path, build_receipt)
        build_receipt_sha256 = sha256_file(build_receipt_path)
        stage_dir.rename(run_dir)
    except Exception:
        if stage_dir.exists():
            shutil.rmtree(stage_dir)
        raise

    latest = {
        "schema": "shared-floor-semantic-latest/v1",
        "run_id": run_id,
        "run_path": f"runs/{run_id}",
        "build_receipt_sha256": build_receipt_sha256,
        "status": verification["status"],
    }
    latest_tmp = output_root / ".latest.json.tmp"
    write_json(latest_tmp, latest)
    os.replace(latest_tmp, output_root / "latest.json")
    return {
        "ok": verification["status"] == "pass",
        "run_id": run_id,
        "run_dir": str(run_dir),
        "build_receipt_sha256": build_receipt_sha256,
        "summary": verification["summary"],
        "disagreement_fixture_ids": verification["disagreement_fixture_ids"],
        "claim_boundary": CLAIM_BOUNDARY,
    }


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output",
        type=Path,
        default=Path("artifacts/shared-floor-semantic-witness"),
        help="Output root containing immutable runs/ and latest.json.",
    )
    parser.add_argument(
        "--created-at",
        default=DEFAULT_RUN_CREATED_AT,
        help="Timezone-aware ISO-8601 evidence epoch.",
    )
    parser.add_argument(
        "--ollama-endpoint",
        default=DEFAULT_OLLAMA_ENDPOINT,
        help="Local Ollama base URL; remote services are outside this witness.",
    )
    parser.add_argument(
        "--models-root",
        type=Path,
        help="Ollama models root; defaults to OLLAMA_MODELS or ~/.ollama/models.",
    )
    parser.add_argument(
        "--changeover-latest",
        type=Path,
        default=DEFAULT_CHANGEOVER_LATEST,
        help=(
            "Path to the immutable changeover-v1 latest.json authority; "
            "its full receipt chain and AI01-AI12 parity are verified first."
        ),
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=DEFAULT_TIMEOUT_SECONDS,
        help="HTTP timeout in seconds for local provenance and embedding calls.",
    )
    parser.add_argument("--json", action="store_true", help="Print canonical JSON.")
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        result = build_run(
            args.output,
            created_at=args.created_at,
            endpoint=args.ollama_endpoint,
            models_root=args.models_root,
            timeout=args.timeout,
            changeover_latest=args.changeover_latest,
        )
    except Exception as exc:  # CLI boundary: machine-readable and fail closed.
        error = {"ok": False, "error": type(exc).__name__, "message": str(exc)}
        if args.json:
            print(canonical_json(error).decode("utf-8"))
        else:
            print(f"ERROR {error['error']}: {error['message']}")
        return 1

    if args.json:
        print(canonical_json(result).decode("utf-8"))
    else:
        summary = result["summary"]
        print(f"PASS {result['run_id']}")
        print(
            f"{summary['topology_agreement_count']}/36 topology agreement; "
            f"{summary['disagreement_count']} visible disagreements; "
            f"{summary['hard_stop_hold_count']}/12 hard-stops held; "
            "0 promotions"
        )
        print(CLAIM_BOUNDARY["claim"])
    return 0 if result["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Render a submission proposal.md into an offline readable HTML report.

This script converts ``proposal.md`` (and its bilingual counterpart when
present) into self-contained offline HTML at ``report/proposal.html``.  The
output must not load any remote resources; all figures are embedded as
``../assets/figures/`` relative paths.

When the proposal declares a ``translation_file`` in its front matter, the
corresponding HTML translation is written alongside the primary report and each
file links to the other with a language-switch anchor.

Evidence markers (``[source:...]``, ``[standard:...]``, ``[depth:...]``,
``[data:...]``, ``[metric:...]``) are rendered as quiet ``<sup>`` labels so
reviewers can trace claims without the markers obscuring prose.

Usage
-----
Run from the repository root or any directory with the path to the proposal::

    python3 scripts/render_proposal_html.py submissions/<login>/<slug>

The output path defaults to ``report/proposal.html`` inside the submission
directory.  Override with ``--out``::

    python3 scripts/render_proposal_html.py submissions/<login>/<slug> \\
        --out report/proposal-preview.html

The script exits 0 on success and 1 when ``proposal.md`` is missing.

Supported Markdown features
----------------------------
- ATX headings (``#`` through ``####``)
- Paragraphs
- Unordered lists (``- item``)
- Fenced code blocks (triple backtick or tilde)
- Inline code, bold, italic, bold-italic
- GitHub-flavored tables (``| col | col |`` with column alignment)
- Block quotes
- Inline images with local paths (remote ``http://`` sources are rejected)
- Evidence markers rendered as ``<sup class="evidence">`` labels
"""

from __future__ import annotations

import argparse
import html
import os
import re
import stat
import tempfile
from pathlib import Path, PurePosixPath
from urllib.parse import unquote_to_bytes


IMAGE_RE = re.compile(r"!\[([^\]]*)\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")
REFERENCE_RE = re.compile(r"\[(source|standard|depth|data|metric):([^\]\s]+)\]")
INLINE_CODE_RE = re.compile(r"`([^`]+)`")
STRONG_EM_RE = re.compile(r"(?<![\\*])\*\*\*(?=\S)(.+?)(?<=\S)\*\*\*(?!\*)", re.S)
STRONG_RE = re.compile(r"(?<![\\*])\*\*(?=\S)(.+?)(?<=\S)\*\*(?!\*)", re.S)
EM_RE = re.compile(r"(?<![\\*])\*(?=\S)(.+?)(?<=\S)\*(?!\*)", re.S)
TABLE_DELIMITER_CELL_RE = re.compile(r"^:?-{3,}:?$")
REFERENCE_LABELS = {
    "zh": {
        "source": "来源",
        "standard": "标准",
        "depth": "深度",
        "data": "空间数据",
        "metric": "指标",
    },
    "en": {
        "source": "Source",
        "standard": "Standard",
        "depth": "Depth",
        "data": "Spatial data",
        "metric": "Metric",
    },
}


def parse_front_matter(text: str) -> tuple[dict[str, str], str]:
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end == -1:
        return {}, text
    raw = text[4:end]
    metadata: dict[str, str] = {}
    for line in raw.splitlines():
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        metadata[key.strip()] = value.strip().strip('"').strip("'")
    return metadata, text[end + 5 :]


def _is_unsafe_url_path_segment(segment: str) -> bool:
    """Return true when URL parsing could reinterpret a filesystem segment."""
    decoded = unquote_to_bytes(segment)
    return (
        decoded in {b".", b".."}
        or b"/" in decoded
        or b"\\" in decoded
        or re.match(rb"^[A-Za-z]:", decoded) is not None
    )


def resolve_local_image(submission_dir: Path, raw_src: str) -> tuple[Path, Path]:
    """Resolve *raw_src* and prove that its target stays in the submission."""
    if re.match(r"^(?:https?:)?//", raw_src, re.I) or re.match(r"^(?:data|file|javascript):", raw_src, re.I):
        raise ValueError(f"remote or unsafe image source is not allowed: {raw_src}")
    clean = raw_src.split("#", 1)[0].split("?", 1)[0]
    pure = PurePosixPath(clean)
    if (
        not clean
        or "\\" in clean
        or pure.is_absolute()
        or not pure.parts
        or ".." in pure.parts
        or any(re.match(r"^[A-Za-z]:", part) for part in pure.parts)
        or any(_is_unsafe_url_path_segment(part) for part in pure.parts)
    ):
        raise ValueError(f"image source must be a relative local path: {raw_src}")
    submission_root = submission_dir.resolve()
    image_path = submission_root.joinpath(*pure.parts).resolve()
    try:
        relative = image_path.relative_to(submission_root)
    except ValueError as exc:
        raise ValueError(
            f"image source must stay within the submission directory: {raw_src}"
        ) from exc
    if not image_path.exists():
        raise ValueError(f"image source is missing: {raw_src}")
    return image_path, relative


def normalize_image_src(submission_dir: Path, raw_src: str) -> str:
    """Resolve *raw_src* to a safe report-relative local path.

    Raises:
        ValueError: If *raw_src* is remote, unsafe, outside the submission, or
            if the target file does not exist.
    """
    _, relative = resolve_local_image(submission_dir, raw_src)
    return "../" + relative.as_posix()


def contained_output_path(submission_dir: Path, raw_path: str) -> Path:
    if "\\" in raw_path:
        raise ValueError(f"output must be a relative path inside the submission: {raw_path}")
    pure = PurePosixPath(raw_path)
    if (
        not raw_path
        or pure.is_absolute()
        or not pure.parts
        or ".." in pure.parts
        or pure.as_posix() != raw_path
        or pure.suffix.lower() != ".html"
    ):
        raise ValueError(f"output must be a relative path inside the submission: {raw_path}")
    path = submission_dir.joinpath(*pure.parts)
    current = submission_dir
    for part in pure.parts:
        current /= part
        if current.is_symlink():
            raise ValueError(f"output path must not use symbolic links: {raw_path}")
    if not path.resolve().is_relative_to(submission_dir):
        raise ValueError(f"output must stay inside the submission: {raw_path}")
    return path


def render_inputs(submission_dir: Path, proposal_paths: list[Path]) -> list[Path]:
    inputs = list(proposal_paths)
    for proposal_path in proposal_paths:
        text = proposal_path.read_text(encoding="utf-8")
        for match in IMAGE_RE.finditer(text):
            raw_src = match.group(2).strip()
            try:
                candidate, _ = resolve_local_image(submission_dir, raw_src)
            except ValueError:
                continue
            if candidate.is_file():
                inputs.append(candidate)
    return inputs


def aliases_path(path: Path, other: Path) -> bool:
    return path.resolve() == other.resolve() or (
        path.exists() and other.exists() and path.samefile(other)
    )


def write_text_atomically(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644
    temporary: str | None = None
    try:
        with tempfile.NamedTemporaryFile(
            dir=path.parent,
            prefix=f".{path.name}-",
            suffix=".tmp",
            delete=False,
            mode="w",
            encoding="utf-8",
        ) as handle:
            temporary = handle.name
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
    except OSError:
        if temporary:
            Path(temporary).unlink(missing_ok=True)
        raise


def render_inline(text: str, language: str = "zh") -> str:
    escaped = html.escape(text)
    code_spans: list[str] = []

    def protect_code(match: re.Match[str]) -> str:
        token = f"\x00CODE{len(code_spans)}\x00"
        code_spans.append(f"<code>{match.group(1)}</code>")
        return token

    escaped = INLINE_CODE_RE.sub(protect_code, escaped)
    escaped = STRONG_EM_RE.sub(r"<strong><em>\1</em></strong>", escaped)
    escaped = STRONG_RE.sub(r"<strong>\1</strong>", escaped)
    escaped = EM_RE.sub(r"<em>\1</em>", escaped)

    def replace_ref(match: re.Match[str]) -> str:
        kind = match.group(1)
        value = match.group(2)
        reference_language = "en" if language == "en" else "zh"
        label = REFERENCE_LABELS[reference_language][kind]
        separator = ": " if reference_language == "en" else "："
        escaped_value = html.escape(value)
        return (
            f'<sup class="evidence evidence-{kind}" data-evidence-kind="{kind}" '
            f'data-evidence-value="{escaped_value}" title="{label}{separator}{escaped_value}">'
            f'{label}</sup>'
        )

    escaped = REFERENCE_RE.sub(replace_ref, escaped)
    for index, code in enumerate(code_spans):
        escaped = escaped.replace(f"\x00CODE{index}\x00", code)
    return escaped.replace(r"\*", "*")


def pipe_is_escaped(line: str, index: int) -> bool:
    backslashes = 0
    index -= 1
    while index >= 0 and line[index] == "\\":
        backslashes += 1
        index -= 1
    return backslashes % 2 == 1


def has_unescaped_pipe(line: str) -> bool:
    for index, char in enumerate(line):
        if char == "|" and not pipe_is_escaped(line, index):
            return True
    return False


def split_table_row(line: str) -> list[str]:
    text = line.strip()
    cells: list[str] = []
    cell: list[str] = []
    index = 0
    while index < len(text):
        char = text[index]
        if char == "|" and pipe_is_escaped(text, index):
            cell.pop()
            cell.append("|")
            index += 1
            continue
        if char == "|":
            cells.append("".join(cell).strip())
            cell = []
        else:
            cell.append(char)
        index += 1
    cells.append("".join(cell).strip())

    if text.startswith("|"):
        cells = cells[1:]
    if text.endswith("|") and not pipe_is_escaped(text, len(text) - 1):
        cells = cells[:-1]
    return cells


def parse_table_delimiter(line: str) -> list[str] | None:
    cells = split_table_row(line)
    if not cells or not all(TABLE_DELIMITER_CELL_RE.fullmatch(cell) for cell in cells):
        return None
    return cells


def table_alignment(delimiter: str) -> str | None:
    if delimiter.startswith(":") and delimiter.endswith(":"):
        return "center"
    if delimiter.endswith(":"):
        return "right"
    if delimiter.startswith(":"):
        return "left"
    return None


def render_table_cell(tag: str, value: str, alignment: str | None, language: str) -> str:
    alignment_class = f' class="align-{alignment}"' if alignment else ""
    return f"<{tag}{alignment_class}>{render_inline(value, language)}</{tag}>"


def render_markdown_body(submission_dir: Path, markdown: str, language: str = "zh") -> str:
    blocks: list[str] = []
    paragraph: list[str] = []
    in_list = False

    def flush_paragraph() -> None:
        nonlocal paragraph
        if paragraph:
            blocks.append(f"<p>{render_inline(' '.join(paragraph), language)}</p>")
            paragraph = []

    def close_list() -> None:
        nonlocal in_list
        if in_list:
            blocks.append("</ul>")
            in_list = False

    lines = markdown.splitlines()
    index = 0
    while index < len(lines):
        line = lines[index].rstrip()
        stripped_line = line.strip()

        if stripped_line.startswith("```") or stripped_line.startswith("~~~"):
            flush_paragraph()
            close_list()
            fence_char = stripped_line[0]
            fence_length = len(stripped_line) - len(stripped_line.lstrip(fence_char))
            code_lines: list[str] = []
            index += 1
            while index < len(lines):
                candidate = lines[index].rstrip()
                candidate_stripped = candidate.strip()
                closing_length = len(candidate_stripped) - len(
                    candidate_stripped.lstrip(fence_char)
                )
                if (
                    closing_length >= fence_length
                    and not candidate_stripped[closing_length:]
                ):
                    index += 1
                    break
                code_lines.append(candidate)
                index += 1
            blocks.append(f"<pre><code>{html.escape(chr(10).join(code_lines))}</code></pre>")
            continue

        if (
            index + 1 < len(lines)
            and stripped_line
            and not line.startswith("#")
            and not line.startswith("- ")
            and not IMAGE_RE.fullmatch(stripped_line)
            and (has_unescaped_pipe(line) or has_unescaped_pipe(lines[index + 1]))
        ):
            delimiter_cells = parse_table_delimiter(lines[index + 1].strip())
            header_cells = split_table_row(line)
            if delimiter_cells is not None and len(header_cells) == len(delimiter_cells):
                flush_paragraph()
                close_list()
                alignments = [table_alignment(cell) for cell in delimiter_cells]
                header = "".join(
                    render_table_cell("th", cell, alignment, language)
                    for cell, alignment in zip(header_cells, alignments)
                )
                index += 2
                body_rows: list[str] = []
                while index < len(lines):
                    row = lines[index].rstrip()
                    stripped = row.strip()
                    if (
                        not stripped
                        or not has_unescaped_pipe(row)
                        or stripped.startswith("#")
                        or stripped.startswith("- ")
                        or stripped.startswith("* ")
                        or stripped.startswith("+ ")
                        or stripped.startswith(">")
                        or stripped.startswith("```")
                        or stripped.startswith("~~~")
                        or re.match(r"^\d{1,9}[.)]\s+", stripped)
                        or IMAGE_RE.fullmatch(stripped)
                    ):
                        break
                    cells = split_table_row(row)
                    cells = (cells + [""] * len(header_cells))[: len(header_cells)]
                    body_rows.append(
                        "<tr>"
                        + "".join(
                            render_table_cell("td", cell, alignment, language)
                            for cell, alignment in zip(cells, alignments)
                        )
                        + "</tr>"
                    )
                    index += 1
                body = f"<tbody>{''.join(body_rows)}</tbody>" if body_rows else ""
                blocks.append(
                    '<div class="proposal-table"><table>'
                    f"<thead><tr>{header}</tr></thead>"
                    f"{body}"
                    "</table></div>"
                )
                continue

        if not line.strip():
            flush_paragraph()
            close_list()
            index += 1
            continue

        image_match = IMAGE_RE.fullmatch(line.strip())
        if image_match:
            flush_paragraph()
            close_list()
            alt = html.escape(image_match.group(1).strip() or "proposal figure")
            src = normalize_image_src(submission_dir, image_match.group(2).strip())
            blocks.append(
                '<figure class="proposal-figure">'
                f'<img src="{html.escape(src)}" alt="{alt}">'
                f"<figcaption>{alt}</figcaption>"
                "</figure>"
            )
            index += 1
            continue

        if stripped_line.startswith(">"):
            flush_paragraph()
            close_list()
            quote_paragraphs: list[list[str]] = [[]]
            while index < len(lines):
                quote_line = lines[index].strip()
                if not quote_line.startswith(">"):
                    break
                quote_text = quote_line[1:].lstrip()
                if quote_text:
                    quote_paragraphs[-1].append(quote_text)
                elif quote_paragraphs[-1]:
                    quote_paragraphs.append([])
                index += 1
            rendered_quotes = "".join(
                f"<p>{render_inline(' '.join(items), language)}</p>"
                for items in quote_paragraphs
                if items
            )
            blocks.append(f"<blockquote>{rendered_quotes}</blockquote>")
            continue

        if line.startswith("#"):
            flush_paragraph()
            close_list()
            level = min(len(line) - len(line.lstrip("#")), 4)
            title = line[level:].strip()
            blocks.append(f"<h{level}>{render_inline(title, language)}</h{level}>")
            index += 1
            continue

        if line.startswith("- "):
            flush_paragraph()
            if not in_list:
                blocks.append("<ul>")
                in_list = True
            blocks.append(f"<li>{render_inline(line[2:].strip(), language)}</li>")
            index += 1
            continue

        paragraph.append(line.strip())
        index += 1

    flush_paragraph()
    close_list()
    return "\n".join(blocks)


def render_html(
    submission_dir: Path,
    proposal_name: str = "proposal.md",
    translation_href: str | None = None,
) -> str:
    proposal_path = submission_dir / proposal_name
    metadata, body = parse_front_matter(proposal_path.read_text(encoding="utf-8"))
    title = metadata.get("title") or submission_dir.name
    summary = metadata.get("summary", "")
    language = metadata.get("language", "zh")
    document_lang = "en" if language == "en" else "zh-CN"
    translation_match = re.search(r"(?m)^# 中文正式译文\s*$", body) if language == "en" else None
    if translation_match:
        english_body = body[: translation_match.start()]
        translation_body = body[translation_match.end() :]
        rendered_body = (
            f'<section lang="en">{render_markdown_body(submission_dir, english_body, "en")}</section>'
            f'<section lang="zh-CN"><h1>中文正式译文</h1>'
            f'{render_markdown_body(submission_dir, translation_body, "zh")}</section>'
        )
    else:
        rendered_body = render_markdown_body(submission_dir, body, language)
    translation_link = ""
    if translation_href:
        link_label = "Read in English" if language == "zh" else "阅读中文版本"
        translation_link = (
            '<p class="translation-link">'
            f'<a href="{html.escape(translation_href)}">{link_label}</a>'
            "</p>"
        )
    return f"""<!doctype html>
<html lang="{document_lang}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{html.escape(title)} - proposal report</title>
<style>
:root {{
  --ink: #172033;
  --muted: #667085;
  --line: #d7dee8;
  --paper: #ffffff;
  --bg: #f4f7fa;
  --accent: #245b8f;
}}
* {{ box-sizing: border-box; }}
body {{
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.75;
}}
main {{
  max-width: 980px;
  margin: 0 auto;
  padding: 42px 24px 72px;
  background: var(--paper);
  min-height: 100vh;
  box-shadow: 0 0 0 1px rgba(23, 32, 51, 0.05);
}}
.hero {{
  border-bottom: 3px solid var(--accent);
  padding-bottom: 24px;
  margin-bottom: 30px;
}}
h1 {{ font-size: 34px; line-height: 1.22; margin: 0 0 10px; }}
h2 {{ font-size: 25px; margin: 34px 0 12px; border-top: 1px solid var(--line); padding-top: 24px; }}
h3 {{ font-size: 20px; margin: 26px 0 10px; }}
p, li {{ font-size: 16px; }}
blockquote {{
  margin: 18px 0;
  padding: 12px 18px;
  border-left: 4px solid var(--line);
  color: var(--muted);
  background: #f8fafc;
}}
code {{
  background: #eef2f7;
  color: #1d4f7a;
  padding: 0.1em 0.35em;
  border-radius: 4px;
}}
.summary {{ color: var(--muted); font-size: 17px; }}
.translation-link a {{ color: var(--accent); font-weight: 700; }}
.proposal-table {{ margin: 20px 0 26px; overflow-x: auto; }}
.proposal-table table {{
  border-collapse: collapse;
  width: 100%;
  min-width: 520px;
  font-size: 15px;
}}
.proposal-table th, .proposal-table td {{
  border: 1px solid var(--line);
  padding: 9px 12px;
  text-align: left;
  vertical-align: top;
  line-height: 1.6;
}}
.proposal-table th {{ background: #eef2f7; color: var(--ink); font-weight: 700; }}
.proposal-table tbody tr:nth-child(even) {{ background: #fafcfe; }}
.proposal-table .align-center {{ text-align: center; }}
.proposal-table .align-right {{ text-align: right; }}
.proposal-figure {{
  margin: 22px 0 28px;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
  background: #f8fafc;
}}
.proposal-figure img {{
  display: block;
  width: 100%;
  height: auto;
}}
.proposal-figure figcaption {{
  padding: 10px 14px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  font-size: 14px;
}}
.evidence {{
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  margin: 0 0.12em;
  border-bottom: 1px solid #8aa8c3;
  color: #315f87;
  font-size: 0.68em;
  font-weight: 650;
  line-height: 1.35;
  vertical-align: super;
}}
@media (max-width: 720px) {{
  main {{ padding: 26px 16px 52px; }}
  h1 {{ font-size: 26px; }}
  h2 {{ font-size: 21px; }}
}}
</style>
</head>
<body>
<main>
<section class="hero">
<h1>{html.escape(title)}</h1>
<p class="summary">{html.escape(summary)}</p>
{translation_link}
</section>
{rendered_body}
</main>
</body>
</html>
"""


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "submission_dir",
        help="Path to the proposal directory, e.g. submissions/<login>/<slug>",
    )
    parser.add_argument(
        "--out",
        default="report/proposal.html",
        help="Output path relative to submission_dir (default: report/proposal.html)",
    )
    args = parser.parse_args()

    submission_dir = Path(args.submission_dir).resolve()
    try:
        out_path = contained_output_path(submission_dir, args.out)
    except ValueError as exc:
        parser.error(str(exc))
    if not (submission_dir / "proposal.md").exists():
        raise SystemExit(f"{submission_dir}/proposal.md is missing")
    primary_path = submission_dir / "proposal.md"
    if primary_path.is_symlink():
        parser.error(f"proposal input must not be a symbolic link: {primary_path}")
    metadata, _ = parse_front_matter(primary_path.read_text(encoding="utf-8"))
    translation_name = metadata.get("translation_file", "")
    translation_path = submission_dir / translation_name if translation_name else None
    translation_output = None
    if (
        translation_path
        and translation_name in {"proposal.zh.md", "proposal.en.md"}
        and translation_path.is_file()
    ):
        if translation_path.is_symlink():
            parser.error(f"proposal input must not be a symbolic link: {translation_path}")
        language = "zh" if translation_name == "proposal.zh.md" else "en"
        try:
            translation_output = contained_output_path(
                submission_dir, f"report/proposal.{language}.html"
            )
        except ValueError as exc:
            parser.error(str(exc))

    inputs = render_inputs(
        submission_dir,
        [primary_path, *([translation_path] if translation_output and translation_path else [])],
    )
    for output in [out_path, *([translation_output] if translation_output else [])]:
        for input_path in inputs:
            if aliases_path(output, input_path):
                parser.error(f"output must not overwrite a rendering input: {input_path}")
    if translation_output and aliases_path(out_path, translation_output):
        parser.error("primary and translated reports must use distinct output paths")

    primary_translation_href = None
    if translation_output:
        primary_translation_href = Path(
            os.path.relpath(translation_output, out_path.parent)
        ).as_posix()
    html_text = render_html(submission_dir, translation_href=primary_translation_href)
    translated_html = None
    if translation_output and translation_path:
        primary_href = Path(os.path.relpath(out_path, translation_output.parent)).as_posix()
        translated_html = render_html(
            submission_dir,
            translation_name,
            translation_href=primary_href,
        )
    write_text_atomically(out_path, html_text)
    print(out_path)
    if translation_output and translated_html is not None:
        write_text_atomically(
            translation_output,
            translated_html,
        )
        print(translation_output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
